                panel.selectWheel(WheelType.BOSSING);
                List<WheelEntry> bosses = new ArrayList<>();
                for (BossDefinition boss : BossCatalog.ALL.subList(0, 12))
                { bosses.add(new WheelEntry(boss.hiscore.name(), boss.name, null, 1)); }
                panel.updatePool(bosses, "12 sample entries. Boss sprites load from the game cache.", panel.generation());
                assertTrue("The sidebar must never contain a wheel", wheels(panel).isEmpty());
                panel.setSize(242, 900); layout(panel);
                image = new BufferedImage(225, panel.getHeight(), BufferedImage.TYPE_INT_RGB);
                g = image.createGraphics(); panel.paint(g); g.dispose();
                ImageIO.write(image, "png", new File("build/reports/wheelbound-bossing-layout.png"));
                panel.selectWheel(WheelType.COMBAT_ACHIEVEMENTS);
                panel.updatePool(List.of(new WheelEntry("CA_1", "Bloodveld", null, 1),
                    new WheelEntry("CA_2", "Obor", null, 1), new WheelEntry("CA_3", "Vorkath", null, 1)),
                    "3 encounters with unfinished tasks.", panel.generation());
                panel.setSize(242, 900); layout(panel);
                image = new BufferedImage(225, panel.getHeight(), BufferedImage.TYPE_INT_RGB);
                g = image.createGraphics(); panel.paint(g); g.dispose();
                ImageIO.write(image, "png", new File("build/reports/wheelbound-combat-achievements.png"));
                for (WheelFilter filter : WheelFilter.values())
                {
                    if (filter.wheel != WheelType.COMBAT_ACHIEVEMENTS) { continue; }
                    AbstractButton box = button(panel, filter.title);
                    assertNotNull(box);
                    assertTrue("Filter must fit its card: " + filter.title,
                        box.getY() + box.getHeight() <= box.getParent().getHeight());
                }
                panel.selectWheel(WheelType.QUESTING);
                panel.updatePool(List.of(new WheelEntry("QUEST_1", "Cook's Assistant", null, 1),
                    new WheelEntry("QUEST_2", "Dragon Slayer I", null, 1)), "2 unfinished quests.", panel.generation());
                panel.setSize(242, 900); layout(panel);
                image = new BufferedImage(242, panel.getHeight(), BufferedImage.TYPE_INT_RGB);
                g = image.createGraphics(); panel.paint(g); g.dispose();
                ImageIO.write(image, "png", new File("build/reports/wheelbound-questing.png"));
                assertTrue("The sidebar must never contain a wheel", wheels(panel).isEmpty());
                for (WheelFilter filter : WheelFilter.values())
                {
                    if (filter.wheel != WheelType.QUESTING) { continue; }
                    AbstractButton box = visibleButton(panel, filter.title);
                    assertNotNull(box);
                    assertTrue(box.getY() + box.getHeight() <= box.getParent().getHeight());
                }
                panel.reset();
            }
            catch (Exception e) { throw new AssertionError(e); }
        });
    }

    /** Check Swing state on the EDT while the test thread waits with a bounded timeout. */
    private static void awaitEdtCondition(java.util.function.BooleanSupplier condition) throws Exception
    {
        java.util.concurrent.CountDownLatch ready = new java.util.concurrent.CountDownLatch(1);
        javax.swing.Timer timer = new javax.swing.Timer(25, event -> {
            if (condition.getAsBoolean()) { ready.countDown(); }
        });
        SwingUtilities.invokeAndWait(timer::start);
        try { assertTrue("Timed out waiting for the wheel", ready.await(8, java.util.concurrent.TimeUnit.SECONDS)); }
        finally { SwingUtilities.invokeAndWait(timer::stop); }
    }

    private static void click(WheelComponent wheel, int x, int y)
    {
        wheel.dispatchEvent(new MouseEvent(wheel, MouseEvent.MOUSE_PRESSED, 0, 0, x, y, 1, false, MouseEvent.BUTTON1));
        wheel.dispatchEvent(new MouseEvent(wheel, MouseEvent.MOUSE_RELEASED, 0, 0, x, y, 1, false, MouseEvent.BUTTON1));
    }
    private static List<WheelComponent> wheels(Container parent)
    {
        List<WheelComponent> found = new ArrayList<>();
        for (Component c : parent.getComponents())
        {
            if (c instanceof WheelComponent) { found.add((WheelComponent)c); }
            else if (c instanceof Container) { found.addAll(wheels((Container)c)); }
        }
        return found;
    }
    private static AbstractButton button(Container parent, String text)
    {
        AbstractButton found = findButton(parent, text);
        if (found == null) { throw new AssertionError("Missing button: " + text); }
        return found;
    }
    private static AbstractButton findButton(Container parent, String text)
    {
        for (Component c : parent.getComponents())
        {
            if (c instanceof AbstractButton && ((AbstractButton)c).getText().contains(text)) { return (AbstractButton)c; }
            if (c instanceof Container)
            {
                AbstractButton found = findButton((Container)c, text);
                if (found != null) { return found; }
            }
        }
        return null;
    }
    private static AbstractButton visibleButton(Container parent, String text)
    {
        for (Component child : parent.getComponents())
        {
            if (!child.isVisible()) { continue; }
            if (child instanceof AbstractButton && text.equals(((AbstractButton)child).getText()))
            { return (AbstractButton)child; }
            if (child instanceof Container)
            {
                AbstractButton found = visibleButton((Container)child, text);
                if (found != null) { return found; }
            }
        }
        return null;
    }

    private static boolean hasLabel(Container parent, String text)
    {
        for (Component c : parent.getComponents())
        {
            if (c instanceof JLabel && ((JLabel)c).getText() != null && ((JLabel)c).getText().contains(text)) { return true; }
            if (c instanceof Container && hasLabel((Container)c, text)) { return true; }
        }
        return false;
    }
    private static void layout(Container c)
    {
        c.doLayout();
        for (Component child : c.getComponents()) { if (child instanceof Container) { layout((Container)child); } }
    }
}

package com.wheelbound;

import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.api.Skill;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;
import org.junit.Test;
import static org.junit.Assert.*;

public class WheelboundBehaviorTest
{
    private BossDefinition boss(HiscoreSkill id)
    {
        return BossCatalog.ALL.stream().filter(b -> b.hiscore == id).findFirst().orElseThrow();
    }

    @Test public void catalogUsesCanonicalSpritesAndNames()
    {
        long count = Arrays.stream(HiscoreSkill.values()).filter(s -> s.getType() == HiscoreSkillType.BOSS).count();
        assertEquals(count, BossCatalog.ALL.size());
        assertEquals(count, BossCatalog.ALL.stream().map(b -> b.hiscore).distinct().count());
        assertEquals(Set.of("Mad Angel", "Maggot King"),
            BossCatalog.ALL.stream().filter(b -> b.profile == null).map(b -> b.name).collect(java.util.stream.Collectors.toSet()));
        for (BossDefinition boss : BossCatalog.ALL)
        {
            assertEquals(boss.hiscore.getName(), boss.name);
            assertEquals(boss.hiscore.getSpriteId(), boss.spriteId);
            assertTrue(boss.spriteId >= 0);
        }
    }

    @Test public void raidModesAreExplicitlyClassified()
    {
        assertEquals(6, BossCatalog.ALL.stream().filter(b -> b.raid).count());
        assertTrue(boss(HiscoreSkill.TOMBS_OF_AMASCUT_EXPERT).raid);
        assertFalse(boss(HiscoreSkill.THE_CORRUPTED_GAUNTLET).raid);
    }

    @Test public void allFilterCombinationsIntersect()
    {
        BossDefinition obor = boss(HiscoreSkill.OBOR);
        BossDefinition raid = boss(HiscoreSkill.CHAMBERS_OF_XERIC);
        BossDefinition hydra = boss(HiscoreSkill.ALCHEMICAL_HYDRA);
        List<BossDefinition> catalog = List.of(obor, raid, hydra);
        for (boolean raids : new boolean[]{false, true})
        {
            for (boolean incomplete : new boolean[]{false, true})
            {
                for (boolean levels : new boolean[]{false, true})
                {
                    List<BossDefinition> result = WheelEligibility.bosses(catalog, raids, incomplete, levels, true,
                        s -> 80, b -> b != obor);
                    assertEquals(!incomplete, result.contains(obor));
                    assertEquals(raids, result.contains(raid));
                    assertEquals(!levels, result.contains(hydra));
                }
            }
        }
    }

    @Test public void realStyleStatsSlayerAndAdditionalRequirements()
    {
        BossProfile melee = boss(HiscoreSkill.OBOR).profile;
        assertFalse(melee.matches(s -> s == Skill.STRENGTH ? 1 : 99));
        assertFalse(melee.matches(s -> s == Skill.PRAYER ? 1 : 99));
        assertTrue(melee.matches(s -> s == Skill.MAGIC || s == Skill.RANGED ? 1 : 99));
        BossProfile hydra = boss(HiscoreSkill.ALCHEMICAL_HYDRA).profile;
        assertFalse(hydra.matches(s -> s == Skill.SLAYER ? 94 : 99));
        assertTrue(hydra.matches(s -> s == Skill.SLAYER ? 95 : 99));
        assertFalse(boss(HiscoreSkill.COMMANDER_ZILYANA).profile.matches(s -> s == Skill.AGILITY ? 69 : 99));
        assertFalse(boss(HiscoreSkill.CHAMBERS_OF_XERIC).profile.matches(s -> s == Skill.MAGIC ? 79 : 99));
        assertTrue(boss(HiscoreSkill.TEMPOROSS).profile.matches(s -> s == Skill.FISHING ? 35 : 1));
    }

    @Test public void unknownRecommendationsAndOfflineStateFailClosed()
    {
        BossDefinition unknown = new BossDefinition(HiscoreSkill.OBOR, false, null, List.of("Obor"));
        assertTrue(WheelEligibility.bosses(List.of(unknown), false, false, true, true, s -> 99, b -> true).isEmpty());
        assertEquals(1, WheelEligibility.bosses(List.of(unknown), false, false, false, false, s -> 1, b -> false).size());
        assertTrue(WheelEligibility.bosses(BossCatalog.ALL, true, true, false, false, s -> 99, b -> true).isEmpty());
        assertTrue(WheelEligibility.bosses(List.of(), true, false, false, true, s -> 99, b -> true).isEmpty());
    }

    @Test public void caAliasesKeepDifferentModesSeparate()
    {
        assertEquals(List.of("Barrows"), boss(HiscoreSkill.BARROWS_CHESTS).caEncounters);
        assertTrue(boss(HiscoreSkill.DAGANNOTH_REX).caEncounters.contains("Dagannoth Kings"));
        assertFalse(boss(HiscoreSkill.THEATRE_OF_BLOOD_HARD_MODE).caEncounters.contains("Theatre of Blood"));
        assertTrue(boss(HiscoreSkill.TZKAL_ZUK).caEncounters.contains("The Inferno"));
    }

    @Test public void completionCacheRefreshesAllWordsAndResetsBetweenAccounts()
    {
        CombatAchievementCache cache = new CombatAchievementCache();
        BossDefinition obor = boss(HiscoreSkill.OBOR);
        Map<String, List<Integer>> mapping = Map.of("Obor", List.of(0, 31, 32));
        AtomicInteger reads = new AtomicInteger();
        cache.refresh("A", mapping, varp -> { reads.incrementAndGet(); return 0; });
        assertEquals(BossData.COMPLETION.length, reads.get());
        assertTrue(cache.hasIncomplete("A", obor));
        assertFalse(cache.hasIncomplete("B", obor));
        for (int i = 0; i < 10; i++) { cache.hasIncomplete("A", obor); }
        assertEquals(BossData.COMPLETION.length, reads.get());
        cache.refresh("A", mapping, varp -> -1);
        assertFalse(cache.hasIncomplete("A", obor));
        cache.refresh("B", mapping, varp -> 0);
        assertFalse(cache.hasIncomplete("A", obor));
        assertTrue(cache.hasIncomplete("B", obor));
        cache.reset();
        assertFalse(cache.isReady("B"));
        assertFalse(cache.hasIncomplete("B", obor));
    }

    @Test public void caPartialCompletionUnknownIdsAndMissingMapping()
    {
        CombatAchievementCache cache = new CombatAchievementCache();
        BossDefinition obor = boss(HiscoreSkill.OBOR);
        cache.refresh("A", Map.of("Obor", List.of(0, 31)), varp -> 1);
        assertTrue(cache.hasIncomplete("A", obor));
        cache.refresh("A", Map.of("Obor", List.of(-1, 100000)), varp -> 0);
        assertFalse(cache.hasIncomplete("A", obor));
        cache.refresh("A", Map.of("Unknown encounter", List.of(0)), varp -> 0);
        assertFalse(cache.hasIncomplete("A", obor));
        cache.refresh(null, Map.of("Obor", List.of(0)), varp -> { fail(); return 0; });
        assertFalse(cache.isReady(null));
    }

    @Test public void onlyCompletionVarpsTriggerRefresh()
    {
        for (int id : BossData.COMPLETION) { assertTrue(CombatAchievementCache.isCompletionVarp(id)); }
        assertFalse(CombatAchievementCache.isCompletionVarp(-1));
        assertFalse(CombatAchievementCache.isCompletionVarp(3138));
        assertTrue(BossData.isComplete(Integer.MIN_VALUE, 31));
        assertFalse(BossData.isComplete(Integer.MIN_VALUE, 30));
    }

    @Test public void skillsExcludeReal99AndOverallButIncludeAllTrainableSkills()
    {
        List<Skill> all = WheelEligibility.skills(false, false, s -> 99);
        assertEquals(Skill.values().length, all.size());
        assertTrue(all.stream().allMatch(Objects::nonNull));
        assertTrue(all.contains(Skill.SAILING));
        assertTrue(all.contains(Skill.ATTACK));
        assertTrue(WheelEligibility.skills(true, true, s -> 99).isEmpty());
        assertTrue(WheelEligibility.skills(true, false, s -> 1).isEmpty());
        assertEquals(List.of(Skill.MINING), WheelEligibility.skills(true, true, s -> s == Skill.MINING ? 98 : 99));
    }

    @Test public void weightedTicketsExactlyMatchVisualWedges()
    {
        List<WheelEntry> entries = XpGoal.entries();
        assertEquals(100, WheelSelection.totalWeight(entries));
        int[] counts = new int[entries.size()];
        for (int ticket = 0; ticket < 100; ticket++) { counts[WheelSelection.indexAt(entries, ticket)]++; }
        for (int i = 0; i < entries.size(); i++) { assertEquals(entries.get(i).weight, counts[i]); }
        assertEquals(1, entries.get(entries.size() - 1).weight);
        assertEquals(1_000_000, XpGoal.MILLION.xp);
        assertEquals(-1, WheelSelection.select(List.of(), new Random(1)));
        assertEquals(-1, WheelSelection.indexAt(entries, 100));
    }

    @Test public void weightedAndEqualWheelsLandAtChosenSliceAfterRepeatedSpins()
    {
        double angle = 0;
        for (List<WheelEntry> entries : List.of(XpGoal.entries(),
            List.of(new WheelEntry("a", "A", null, 1), new WheelEntry("b", "B", null, 1))))
        {
            for (int selected = 0; selected < entries.size(); selected++)
            {
                double end = WheelSelection.targetAngle(angle, entries, selected);
                assertTrue(end - angle >= 1800);
                assertEquals(90, ((WheelSelection.center(entries, selected) - end) % 360 + 360) % 360, .000001);
                angle = end;
            }
        }
    }

    @Test public void fullBossPoolGivesEachGroupedEncounterOneTicket()
    {
        List<WheelEntry> entries = WheelEntry.groupRaids(BossCatalog.ALL.stream()
            .map(b -> new WheelEntry(b.hiscore.name(), b.name, null, 1))
            .collect(java.util.stream.Collectors.toList()));
        assertEquals(entries.size(), WheelSelection.totalWeight(entries));
        assertEquals(entries.size(), entries.stream().map(e -> e.id).distinct().count());
        for (int ticket = 0; ticket < entries.size(); ticket++)
        { assertEquals(ticket, WheelSelection.indexAt(entries, ticket)); }
    }
}

package com.wheelbound;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import javax.swing.SwingUtilities;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.events.RuneScapeProfileChanged;
import org.junit.Test;
import static org.junit.Assert.*;

public class WheelboundEventsTest
{
    @Test public void ordinaryVarbitBurstsWaitForOneGameTick() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            try
            {
                WheelboundPlugin plugin = new WheelboundPlugin();
                set(plugin, "active", true);
                VarbitChanged event = new VarbitChanged(); event.setVarpId(3138);
                for (int i = 0; i < 100; i++) { plugin.onVarbitChanged(event); }
                java.util.concurrent.atomic.AtomicBoolean queued =
                    (java.util.concurrent.atomic.AtomicBoolean)get(plugin, "poolRefreshQueued");
                assertFalse(queued.get()); assertEquals(true, get(plugin, "poolDirty"));
                plugin.onGameTick(new net.runelite.api.events.GameTick());
                assertTrue(queued.get()); assertEquals(false, get(plugin, "poolDirty"));
                plugin.onGameTick(new net.runelite.api.events.GameTick());
                assertEquals(false, get(plugin, "poolDirty"));
                set(plugin, "active", false);
            }
            catch (Exception ex) { throw new AssertionError(ex); }
        });
    }

    @Test public void enablingAndDisablingOnEdtAddsAndRemovesSidebar() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            try
            {
                WheelboundPlugin plugin = new WheelboundPlugin();
                net.runelite.client.ui.ClientToolbar toolbar = org.mockito.Mockito.mock(net.runelite.client.ui.ClientToolbar.class);
                set(plugin, "toolbar", toolbar);
                set(plugin, "gson", net.runelite.http.api.RuneLiteAPI.GSON);
                set(plugin, "settings", org.mockito.Mockito.mock(net.runelite.client.config.ConfigManager.class));
                QueuedThread thread = new QueuedThread();
                set(plugin, "clientThread", thread);
                set(plugin, "popup", new WheelPopup(null));
                set(plugin, "overlays", org.mockito.Mockito.mock(net.runelite.client.ui.overlay.OverlayManager.class));
                set(plugin, "mouseManager", org.mockito.Mockito.mock(net.runelite.client.input.MouseManager.class));
                set(plugin, "keyManager", org.mockito.Mockito.mock(net.runelite.client.input.KeyManager.class));
                for (int i = 0; i < 2; i++)
                {
                    plugin.startUp();
                    net.runelite.client.ui.NavigationButton button = (net.runelite.client.ui.NavigationButton)get(plugin, "navigation");
                    assertNotNull(button.getIcon());
                    assertSame(get(plugin, "panel"), button.getPanel());
                    org.mockito.Mockito.verify(toolbar).addNavigation(button);
                    CombatAchievementCache cache = (CombatAchievementCache)get(plugin, "achievements");
                    cache.refresh("A", java.util.Map.of("Obor", List.of(0)), id -> 0);
                    plugin.shutDown();
                    assertTrue("Cleanup waits for the client thread", cache.isReady("A"));
                    thread.work.forEach(Runnable::run);
                    thread.work.clear();
                    assertFalse("Client-thread cleanup clears account data", cache.isReady("A"));
                    org.mockito.Mockito.verify(toolbar).removeNavigation(button);
                    assertNull(get(plugin, "panel"));
                    assertNull(get(plugin, "navigation"));
                }
                // Shutdown must also tolerate an incomplete startup.
                plugin.shutDown();
            }
            catch (Exception e) { throw new AssertionError(e); }
        });
    }

    @Test public void completionEventBurstsQueueOneRefreshAndIgnoreOtherVarps() throws Exception
    {
        WheelboundPlugin plugin = new WheelboundPlugin();
        QueuedThread thread = new QueuedThread();
        set(plugin, "clientThread", thread); set(plugin, "active", true);
        VarbitChanged event = new VarbitChanged(); event.setVarpId(3138);
        plugin.onVarbitChanged(event);
        assertEquals(0, thread.work.size());
        for (int id : BossData.COMPLETION)
        {
            event.setVarpId(id); plugin.onVarbitChanged(event);
        }
        assertEquals(1, thread.work.size());
        set(plugin, "active", false);
        thread.work.remove(0).run();
    }

    @Test public void loginRefreshesAndProfileChangeInvalidatesPendingResponses() throws Exception
    {
        WheelboundPlugin plugin = new WheelboundPlugin();
        QueuedThread thread = new QueuedThread();
        set(plugin, "clientThread", thread); set(plugin, "active", true);
        GameStateChanged login = new GameStateChanged(); login.setGameState(GameState.LOGGED_IN);
        plugin.onGameStateChanged(login);
        assertEquals(1, thread.work.size());
        long before = ((java.util.concurrent.atomic.AtomicLong)get(plugin, "session")).get();
        plugin.onRuneScapeProfileChanged(new RuneScapeProfileChanged("A", "B"));
        assertTrue(((java.util.concurrent.atomic.AtomicLong)get(plugin, "session")).get() > before);
        assertEquals(2, thread.work.size());
        set(plugin, "active", false);
        thread.work.forEach(Runnable::run);
    }

    @Test public void logoutClearsCachedEligibilityAndCancelsThePanel() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            try
            {
                WheelboundPlugin plugin = new WheelboundPlugin();
                set(plugin, "clientThread", new QueuedThread()); set(plugin, "active", true);
                set(plugin, "panel", new WheelboundPanel(net.runelite.http.api.RuneLiteAPI.GSON, k -> null, (k, v) -> {}));
                CombatAchievementCache cache = (CombatAchievementCache)get(plugin, "achievements");
                cache.refresh("A", java.util.Map.of("Obor", List.of(0)), id -> 0);
                assertTrue(cache.isReady("A"));
                GameStateChanged logout = new GameStateChanged(); logout.setGameState(GameState.LOGIN_SCREEN);
                plugin.onGameStateChanged(logout);
                assertFalse(cache.isReady("A"));
                set(plugin, "active", false);
            }
            catch (Exception e) { throw new AssertionError(e); }
        });
    }

    private static final class QueuedThread extends ClientThread
    {
        final List<Runnable> work = new ArrayList<>();
        @Override public void invokeLater(Runnable action) { work.add(action); }
    }
    private static Object get(Object target, String name) throws Exception
    {
        Field field = target.getClass().getDeclaredField(name); field.setAccessible(true); return field.get(target);
    }
    private static void set(Object target, String name, Object value) throws Exception
    {
        Field field = target.getClass().getDeclaredField(name); field.setAccessible(true); field.set(target, value);
    }
}

