            wheel[0].setEntries(entries); wheel[0].setAvailable(true);
            wheel[0].setSpinAction(() -> {
                starts.incrementAndGet();
                wheel[0].animate(entries, 0, () -> fail("Cancelled spin completed"));
            });
            popup[0].show("Bossing", wheel[0], "", wheel[0]::requestSpin, () -> {
