package com.wheelbound;

import java.util.Arrays;
import java.util.List;
import java.util.Set;
import java.util.function.Predicate;
import java.util.function.ToIntFunction;
import java.util.stream.Collectors;
import net.runelite.api.Skill;

final class WheelEligibility
{
    private WheelEligibility() {}

    static List<BossDefinition> bosses(List<BossDefinition> catalog, boolean raids, boolean onlyIncomplete,
        boolean limitLevels, boolean loggedIn, ToIntFunction<Skill> levels, Predicate<BossDefinition> incomplete)
    {
        if (!loggedIn && (limitLevels || onlyIncomplete)) { return List.of(); }
        return catalog.stream()
            .filter(b -> raids || !b.raid)
            .filter(b -> !limitLevels || b.profile != null && b.profile.matches(levels))
            .filter(b -> !onlyIncomplete || incomplete.test(b))
            .collect(Collectors.toUnmodifiableList());
    }

    static List<Skill> skills(boolean exclude99, boolean loggedIn, ToIntFunction<Skill> levels)
    { return skills(false, exclude99, loggedIn, levels); }

    static List<Skill> skills(boolean excludeCombat, boolean exclude99, boolean loggedIn, ToIntFunction<Skill> levels)
    {
        if (exclude99 && !loggedIn) { return List.of(); }
        return Arrays.stream(Skill.values())
            .filter(s -> !excludeCombat || !COMBAT_SKILLS.contains(s))
            .filter(s -> !exclude99 || levels.applyAsInt(s) < 99)
            .collect(Collectors.toUnmodifiableList());
    }

    static List<PetDefinition> pets(Set<WheelFilter> filters)
    {
        return PetDefinition.ALL.stream().filter(pet -> {
            switch (pet.kind)
            {
                case BOSS: return filters.contains(WheelFilter.PET_BOSSES);
                case RAID: return filters.contains(WheelFilter.PET_RAIDS);
                case SKILL: return filters.contains(WheelFilter.PET_SKILLS);
                case ACTIVITY: return filters.contains(WheelFilter.PET_ACTIVITIES);
                default: throw new IllegalStateException("Unknown pet source");
            }
        }).collect(Collectors.toUnmodifiableList());
    }

    private static final Set<Skill> COMBAT_SKILLS = Set.of(Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE,
        Skill.HITPOINTS, Skill.RANGED, Skill.MAGIC, Skill.PRAYER);

    static List<CaEncounter> achievements(List<CaEncounter> encounters, boolean excludeBosses, boolean excludeRaids,
        Predicate<CaEncounter> hasTasks, Predicate<CaEncounter> taskAvailable)
    {
        return encounters.stream().filter(e -> !excludeBosses || e.kind != CaEncounter.Kind.BOSS)
            .filter(e -> !excludeRaids || e.kind != CaEncounter.Kind.RAID)
            .filter(hasTasks).filter(taskAvailable).collect(Collectors.toUnmodifiableList());
    }
}

package com.wheelbound;

/** Declarative sidebar sections; new wheels can register their own filter controls here. */
enum WheelFilter
{
    ACCOUNT(WheelType.BOSSING, "Account", "bossAccount", "Filter by Skill Level", true,
        "Check recommended real levels and known quest/access requirements."),
    BOSS_TASK(WheelType.BOSSING, "Account", "bossIncludeSlayerTask", "Include Slayer-task bosses", true,
        "Include task-only bosses only with a matching active assignment and location."),
    BOSS_RAIDS(WheelType.BOSSING, "Boss pool", "bossIncludeRaids", "Include raids", true, "Include raids within the selected difficulty tiers."),
    MIMIC(WheelType.BOSSING, "Boss pool", "bossIncludeMimic", "Include Mimic", true, "Include Mimic within the selected difficulty tiers."),
    BOSS_EASY(BossDifficulty.EASY), BOSS_MEDIUM(BossDifficulty.MEDIUM), BOSS_HARD(BossDifficulty.HARD),
    BOSS_ELITE(BossDifficulty.ELITE), BOSS_MASTER(BossDifficulty.MASTER), BOSS_GRANDMASTER(BossDifficulty.GRANDMASTER),
    BOSS_UNRATED(BossDifficulty.UNRATED),
    QUEST_NOVICE("Novice"), QUEST_INTERMEDIATE("Intermediate"), QUEST_EXPERIENCED("Experienced"),
    QUEST_MASTER("Master"), QUEST_GRANDMASTER("Grandmaster"), QUEST_SPECIAL("Special"),
    QUEST_ELIGIBLE(WheelType.QUESTING, "Requirements", "questEligibleOnly", "Exclude ineligible quests", true,
        "Use the game's quest requirement checks, including real levels and prerequisite quests."),
    PET_OWNED(WheelType.PET_HUNTING, "Account", "petExcludeOwned", "Exclude pets already owned", true,
        "Exclude unlocked pets, including lost pets that can be reclaimed. Requires login."),
    COMBAT_SKILLS(WheelType.SKILLING, "Skills", "skillExcludeCombat", "Exclude combat skills", false,
        "Remove Attack, Strength, Defence, Hitpoints, Ranged, Magic and Prayer. Slayer remains a training skill."),
    MAXED_SKILLS(WheelType.SKILLING, "Skills", "skillExclude99", "Exclude skills with 99", true, "Use real levels, not boosted or virtual levels."),
    XP(WheelType.SKILLING, "XP target", "includeXpGoal", "Include XP goal", false, "Spin the existing second XP wheel after choosing a skill."),
    CA_SPECIFIC(WheelType.COMBAT_ACHIEVEMENTS, "Result", "caSpecificAchievement", "Pick a specific achievement", false,
        "Show a random unfinished achievement below the selected encounter, using your included tiers."),
    CA_BOSSES(WheelType.COMBAT_ACHIEVEMENTS, "Encounters", "caIncludeBosses", "Include bosses", true,
        "Include boss encounters. Raids have their own separate filter."),
    CA_RAIDS(WheelType.COMBAT_ACHIEVEMENTS, "Encounters", "caIncludeRaids", "Include raids", true, "Include raid encounters across all modes."),
    CA_TASK(WheelType.COMBAT_ACHIEVEMENTS, "Encounters", "caSlayerTask", "Match my Slayer task", true,
        "Task-only encounters need a matching active task and location."),
    PET_BOSSES(WheelType.PET_HUNTING, "Pet sources", "petIncludeBosses", "Include bosses", true, "Include boss pets, including skilling bosses."),
    PET_RAIDS(WheelType.PET_HUNTING, "Pet sources", "petIncludeRaids", "Include raids", true, "Include one base pet per raid."),
    PET_SKILLS(WheelType.PET_HUNTING, "Pet sources", "petIncludeSkills", "Include skilling", true, "Include pets from skills and Hunter activities."),
    PET_ACTIVITIES(WheelType.PET_HUNTING, "Pet sources", "petIncludeActivities", "Include other activities", true, "Include minigames, master clues and chompy hunting."),
    EASY(CaTier.EASY), MEDIUM(CaTier.MEDIUM), HARD(CaTier.HARD),
    ELITE(CaTier.ELITE), MASTER(CaTier.MASTER), GRANDMASTER(CaTier.GRANDMASTER);

    final WheelType wheel;
    final String section, key, title, tip;
    final boolean defaultValue;
    final CaTier tier;
    WheelFilter(WheelType wheel, String section, String key, String title, boolean defaultValue, String tip)
    { this.wheel = wheel; this.section = section; this.key = key; this.title = title; this.defaultValue = defaultValue; this.tip = tip; tier = null; }
    WheelFilter(CaTier tier)
    {
        wheel = WheelType.COMBAT_ACHIEVEMENTS; section = "Include task tiers";
        key = "caInclude" + tier.title; title = "Include " + tier.title; defaultValue = true;
        tip = "Include unfinished " + tier.title + " tasks when deciding which encounters to include.";
        this.tier = tier;
    }
    WheelFilter(BossDifficulty difficulty)
    { this(WheelType.BOSSING, "Boss difficulty", "bossInclude" + difficulty.title, difficulty.title, true,
        "Bossing Ladder difficulty; independent of your account levels. Unrated covers unlisted bosses."); }
    WheelFilter(String difficulty)
    { this(WheelType.QUESTING, "Quest difficulty", "questInclude" + difficulty, difficulty, true,
        "Include unfinished " + difficulty.toLowerCase() + " quests."); }
    String savedValue(java.util.function.Function<String, String> load)
    {
        String value = load.apply(key);
        if (value == null && this == BOSS_RAIDS)
        {
            String previous = load.apply("bossExcludeRaids");
            value = previous != null ? Boolean.toString(!Boolean.parseBoolean(previous)) : load.apply("includeRaids");
        }
        if (value == null && this == MIMIC && load.apply("bossExcludeMimic") != null)
        { value = Boolean.toString(!Boolean.parseBoolean(load.apply("bossExcludeMimic"))); }
        if (value == null && key.startsWith("caInclude"))
        {
            String previous = load.apply(key.replace("caInclude", "caExclude"));
            if (previous != null) { value = Boolean.toString(!Boolean.parseBoolean(previous)); }
        }
        return value;
    }
}

package com.wheelbound;

import java.util.List;
import net.runelite.client.hiscore.HiscoreSkill;

/** Canonical art/name plus Wheelbound's tunable recommendations and local CA encounter aliases. */
final class BossDefinition
{
    final HiscoreSkill hiscore;
    final String name;
    final int spriteId;
    final boolean raid;
    final BossProfile profile;
    final List<String> caEncounters;

    BossDefinition(HiscoreSkill hiscore, boolean raid, BossProfile profile, List<String> caEncounters)
    {
        this.hiscore = hiscore;
        this.name = hiscore.getName();
        this.spriteId = hiscore.getSpriteId();
        this.raid = raid;
        this.profile = profile;
        this.caEncounters = List.copyOf(caEncounters);
    }
}

package com.wheelbound;

import com.google.inject.Provides;
import com.google.gson.Gson;
import java.util.List;
import java.util.Set;
import java.util.EnumSet;
import java.util.function.Predicate;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicLong;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(name = "Wheelbound", description = "Choose a boss, skill, quest, pet hunt or unfinished Combat Achievement encounter.",
    tags = {"wheel", "randomizer", "bossing", "skilling", "combat achievements", "pets", "quests"})
public class WheelboundPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ClientToolbar toolbar;
    @Inject private ConfigManager settings;
    @Inject private Gson gson;
    @Inject private WheelIconProvider icons;
    @Inject private WheelPopup popup;
    @Inject private net.runelite.client.ui.overlay.OverlayManager overlays;
    @Inject private net.runelite.client.input.MouseManager mouseManager;
    @Inject private net.runelite.client.input.KeyManager keyManager;
    private final BossData bossData = new BossData();
    private final CombatAchievementCache achievements = new CombatAchievementCache();
    private final AtomicBoolean caRefreshQueued = new AtomicBoolean();
    private final AtomicBoolean poolRefreshQueued = new AtomicBoolean();
    private boolean poolDirty;
    private volatile WheelboundPanel panel;
    private NavigationButton navigation;
    private volatile boolean active;
    private final AtomicLong session = new AtomicLong();
    private final java.util.Map<net.runelite.api.Skill, Integer> levels = new java.util.EnumMap<>(net.runelite.api.Skill.class);

    @Override protected void startUp()
    {
        long epoch = session.incrementAndGet();
        active = true;
        // RuneLite invokes plugin lifecycle methods on the EDT already.
        panel = new WheelboundPanel(gson, key -> settings.getConfiguration("wheelbound", key),
            (key, value) -> settings.setConfiguration("wheelbound", key, value));
        panel.setAction(this::request);
        panel.setRefreshAction(this::queueCaRefresh);
        panel.setPopup(popup);
        overlays.add(popup);
        mouseManager.registerMouseListener(popup.mouse);
        mouseManager.registerMouseWheelListener(popup.mouseWheel);
        keyManager.registerKeyListener(popup);
        navigation = NavigationButton.builder().tooltip("Wheelbound").icon(WheelStyle.createIcon())
            .priority(5).panel(panel).build();
        toolbar.addNavigation(navigation);
        clientThread.invokeLater(() -> { if (active && session.get() == epoch) { resetAccount(); queueCaRefresh(); } });
    }

    @Override protected void shutDown()
    {
        active = false;
        long epoch = session.incrementAndGet();
        clientThread.invokeLater(() -> {
            if (!active && session.get() == epoch)
            { achievements.reset(); bossData.clear(); levels.clear(); poolDirty = false; }
        });
        caRefreshQueued.set(false); poolRefreshQueued.set(false);
        popup.hide();
        overlays.remove(popup);
        mouseManager.unregisterMouseListener(popup.mouse);
        mouseManager.unregisterMouseWheelListener(popup.mouseWheel);
        keyManager.unregisterKeyListener(popup);
        if (panel != null)
        {
            panel.setAction(ignored -> {}); panel.setRefreshAction(() -> {}); panel.reset(); panel = null;
        }
        if (navigation != null)
        {
            toolbar.removeNavigation(navigation); navigation = null;
        }
    }

    @Subscribe public void onGameStateChanged(GameStateChanged event)
    {
        switch (event.getGameState())
        {
            case LOGGED_IN: queueCaRefresh(); break;
            case LOGIN_SCREEN: case HOPPING: case CONNECTION_LOST: case LOGGING_IN:
                resetAccount(); break;
            default: break;
        }
    }

    @Subscribe public void onRuneScapeProfileChanged(RuneScapeProfileChanged ignored)
    {
        // Invalidate outstanding UI responses immediately, before the queued local read.
        session.incrementAndGet();
        WheelboundPanel target = panel;
        clientThread.invokeLater(() -> { if (active && target != null && panel == target) { resetAccount(); queueCaRefresh(); } });
    }

    // Invoked by RuneLite's event bus.
    @SuppressWarnings("unused")
    @Subscribe public void onProfileChanged(ProfileChanged ignored)
    {
        session.incrementAndGet();
        WheelboundPanel target = panel;
        SwingUtilities.invokeLater(() -> {
            if (active && target != null && panel == target)
            { target.reloadPreferences(key -> settings.getConfiguration("wheelbound", key)); request(false); }
        });
        clientThread.invokeLater(() -> { if (active && target != null && panel == target) { resetAccount(); queueCaRefresh(); } });
    }

    @Subscribe public void onVarbitChanged(VarbitChanged event)
    {
        if (CombatAchievementCache.isCompletionVarp(event.getVarpId())) { queueCaRefresh(); }
        else { poolDirty = true; }
    }

    @Subscribe public void onGameTick(GameTick ignored)
    {
        if (poolDirty) { poolDirty = false; queuePoolRefresh(); }
    }

    // Invoked by RuneLite's event bus.
    @SuppressWarnings("unused")
    @Subscribe public void onStatChanged(StatChanged event)
    {
        Integer previous = levels.put(event.getSkill(), event.getLevel());
        if (previous == null || previous != event.getLevel()) { poolDirty = true; }
    }

    private boolean loggedIn() { return client.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null; }
    private String identity()
    {
        String profile = settings.getRSProfileKey();
        return loggedIn() && profile != null ? client.getAccountHash() + ":" + profile : null;
    }

    private void resetAccount()
    {
        long epoch = session.incrementAndGet();
        achievements.reset(); levels.clear(); poolDirty = false;
        SwingUtilities.invokeLater(() -> {
            if (active && session.get() == epoch) { panel.reset(); request(false); }
        });
    }

    /** Coalesces a burst of completion-varp events; never reads CAs per tick or per spin. */
    private void queueCaRefresh()
    {
        if (!active || !caRefreshQueued.compareAndSet(false, true)) { return; }
        clientThread.invokeLater(() -> {
            caRefreshQueued.set(false);
            if (!active) { return; }
            achievements.reset();
            if (loggedIn())
            {
                try { achievements.refresh(identity(), bossData.load(client), client::getVarpValue); }
                catch (RuntimeException ex) { log.debug("Local combat achievement data is unavailable", ex); }
            }
            queuePoolRefresh();
        });
    }

    private void queuePoolRefresh()
    {
        if (!active || !poolRefreshQueued.compareAndSet(false, true)) { return; }
        SwingUtilities.invokeLater(() -> {
            poolRefreshQueued.set(false);
            if (active && panel != null) { request(false); }
        });
    }

    /** Preferences are captured on the EDT; all player reads and sprite loading use the client thread. */
    private void request(boolean spin)
    {
        if (!active || panel == null) { return; }
        if (panel.wheelType() == WheelType.CUSTOM) { panel.refreshCustomPool(spin); return; }
        WheelType type = panel.wheelType();
        Set<WheelFilter> filters = panel.selectedFilters();
        long revision = panel.generation(), epoch = session.get();
        clientThread.invokeLater(() -> {
            if (!active || session.get() != epoch) { return; }
            List<WheelEntry> entries;
            String message;
            WheelEntry completion = null;
            boolean loggedIn = loggedIn();
            boolean matchTask = filters.contains(type == WheelType.BOSSING ? WheelFilter.BOSS_TASK : WheelFilter.CA_TASK);
            AccountAccess.SlayerTask task = AccountAccess.SlayerTask.unavailable();
            if (loggedIn && type != WheelType.SKILLING && matchTask)
            {
                try { task = AccountAccess.slayerTask(client); }
                catch (RuntimeException ex) { log.debug("Slayer assignment is unavailable", ex); }
            }
            AccountAccess.SlayerTask assignment = task;
            if (type == WheelType.BOSSING)
            {
                boolean accountFilter = filters.contains(WheelFilter.ACCOUNT);
                Predicate<BossDefinition> access = AccountAccess.requirements(client);
                List<BossDefinition> eligible = WheelEligibility.bosses(BossCatalog.ALL,
                    filters.contains(WheelFilter.BOSS_RAIDS), false, accountFilter, loggedIn,
                    client::getRealSkillLevel, boss -> true).stream()
                    .filter(b -> BossDifficulty.included(b, filters))
                    .filter(b -> filters.contains(WheelFilter.MIMIC) || !b.name.equals("Mimic"))
                    .filter(b -> AccountAccess.taskAllows(b.name,
                        matchTask ? assignment : AccountAccess.SlayerTask.unavailable()))
                    .filter(b -> {
                        if (!accountFilter) { return true; }
                        try { return access.test(b); }
                        catch (RuntimeException ex) { log.debug("Access data is unavailable for {}", b.name, ex); return false; }
                    }).collect(Collectors.toUnmodifiableList());
                entries = eligible.stream().map(icons::boss).collect(Collectors.toList());
                message = eligible.size() + " eligible bosses. All appear in the centered wheel with equal odds.";
                if (!loggedIn && accountFilter)
                { message = "Log in to check your levels and quest access, or turn off Filter by Skill Level."; }
                else if (entries.isEmpty())
                { message = "No bosses match. Adjust the account or pool filters."; }
            }
            else if (type == WheelType.SKILLING)
            {
                boolean exclude99 = filters.contains(WheelFilter.MAXED_SKILLS);
                entries = WheelEligibility.skills(filters.contains(WheelFilter.COMBAT_SKILLS), exclude99, loggedIn, client::getRealSkillLevel)
                    .stream().map(icons::skill).collect(Collectors.toList());
                message = entries.size() + " eligible skills. Open the centered wheel to spin.";
                if (!loggedIn && exclude99) { message = "Log in to exclude level 99 skills."; }
                else if (entries.isEmpty()) { message = "No skills match. Adjust the combat or level-99 filters."; }
            }
            else if (type == WheelType.PET_HUNTING)
            {
                entries = List.of();
                boolean excludeOwned = filters.contains(WheelFilter.PET_OWNED);
                if (excludeOwned && !loggedIn) { message = "Log in to exclude pets already owned."; }
                else
                {
                    try
                    {
                        Set<Integer> owned = excludeOwned ? OwnedPets.read(client) : Set.of();
                        entries = WheelEligibility.pets(filters).stream()
                            .filter(pet -> !excludeOwned || !OwnedPets.contains(owned, pet))
                            .map(icons::pet).collect(Collectors.toList());
                        message = entries.isEmpty() ? "No pets match your ownership and source filters."
                            : entries.size() + " eligible pets. Each has equal wheel odds.";
                    }
                    catch (RuntimeException ex)
                    { log.debug("Pet ownership data is unavailable", ex); message = "Pet data unavailable. Change a checkbox to retry."; }
                }
            }
            else if (type == WheelType.QUESTING)
            {
                entries = List.of();
                if (!loggedIn) { message = "Log in to load your unfinished quests."; }
                else
                {
                    try
                    {
                        QuestPool quests = QuestPool.read(client, filters, icons);
                        entries = quests.entries;
                        message = quests.allComplete ? QuestPool.COMPLETE : entries.isEmpty()
                            ? "No unfinished quests match. Adjust difficulty or requirement filters."
                            : entries.size() + " unfinished quests. Each has equal wheel odds.";
                        if (quests.allComplete) { completion = icons.quest(-1, "All quests completed!"); }
                    }
                    catch (RuntimeException ex)
                    { log.debug("Quest data unavailable", ex); message = "Quest data unavailable. Change a checkbox to retry."; }
                }
            }
            else
            {
                String account = identity();
                Set<CaTier> excluded = EnumSet.noneOf(CaTier.class);
                for (WheelFilter filter : WheelFilter.values()) { if (filter.tier != null && !filters.contains(filter)) { excluded.add(filter.tier); } }
                entries = List.of();
                if (!loggedIn) { message = "Log in to load your unfinished Combat Achievements."; }
                else if (!achievements.isReady(account)) { message = "Local Combat Achievement data is unavailable. Change a checkbox to retry."; }
                else
                {
                    entries = WheelEligibility.achievements(bossData.encounters(client), !filters.contains(WheelFilter.CA_BOSSES),
                        !filters.contains(WheelFilter.CA_RAIDS), e -> achievements.hasIncomplete(account, e, excluded),
                        e -> !matchTask || AccountAccess.taskAllows(e.name, assignment))
                        .stream().map(e -> {
                            WheelEntry entry = icons.encounter(e);
                            return filters.contains(WheelFilter.CA_SPECIFIC)
                                ? entry.withTasks(achievements.incompleteTasks(account, e, excluded)) : entry;
                        }).collect(Collectors.toUnmodifiableList());
                    message = entries.isEmpty() ? "No unfinished tasks match. Include another tier or encounter category."
                        : entries.size() + " encounters with unfinished tasks in your included tiers.";
                }
            }
            List<WheelEntry> snapshot = WheelEntry.groupRaids(entries);
            String info = message;
            WheelEntry completedQuests = completion;
            SwingUtilities.invokeLater(() -> {
                if (!active || epoch != session.get() || revision != panel.generation()) { return; }
                if (spin) { panel.spinResponse(snapshot, info, revision); }
                else { panel.updatePool(snapshot, info, revision); }
                panel.setQuestCompletion(completedQuests);
            });
        });
    }

    // Invoked by Guice when resolving the configuration binding.
    @SuppressWarnings("unused")
    @Provides WheelboundConfig provideConfig(ConfigManager manager) { return manager.getConfig(WheelboundConfig.class); }
}

package com.wheelbound;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.VarPlayerID;

/** Read-only game-cache metadata and character completion flags. Client thread only. */
final class BossData
{
	// Cache schema also documented by Combat Achievements Tracker's DataLoader:
	// https://github.com/ehubbartt/combat-achievements-tracker
	private static final int BOSS_NAMES = 3971;
	private static final int TASK_ID = 1306;
	private static final int TASK_BOSS = 1312;
	static final int[] COMPLETION = {
		VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1,
		VarPlayerID.CA_TASK_COMPLETED_2, VarPlayerID.CA_TASK_COMPLETED_3,
		VarPlayerID.CA_TASK_COMPLETED_4, VarPlayerID.CA_TASK_COMPLETED_5,
		VarPlayerID.CA_TASK_COMPLETED_6, VarPlayerID.CA_TASK_COMPLETED_7,
		VarPlayerID.CA_TASK_COMPLETED_8, VarPlayerID.CA_TASK_COMPLETED_9,
		VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
		VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13,
		VarPlayerID.CA_TASK_COMPLETED_14, VarPlayerID.CA_TASK_COMPLETED_15,
		VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
		VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19,
		VarPlayerID.CA_TASK_COMPLETED_20
	};
	private final Map<String, List<Integer>> tasks = new TreeMap<>();
	private List<CaEncounter> encounters = List.of();

	void clear()
	{
		tasks.clear();
		encounters = List.of();
	}

	List<CaEncounter> encounters(Client client) { load(client); return encounters; }

	Map<String, List<Integer>> load(Client client)
	{
		if (!tasks.isEmpty())
		{
			return java.util.Collections.unmodifiableMap(tasks);
		}
		Map<String, List<Integer>> loaded = new TreeMap<>();
		Map<Integer, List<CaEncounter.Task>> tiered = new TreeMap<>();
		Map<Integer, String> encounterNames = new TreeMap<>();
		EnumComposition names = client.getEnum(BOSS_NAMES);
		if (names == null) { throw new IllegalStateException("Encounter names unavailable"); }
		for (CaTier tier : CaTier.values())
		{
			EnumComposition entries = client.getEnum(tier.enumId);
			if (entries == null || entries.getIntVals() == null || entries.getIntVals().length == 0)
			{
				throw new IllegalStateException("Achievement tier unavailable");
			}
			for (int structId : entries.getIntVals())
			{
				StructComposition task = client.getStructComposition(structId);
				if (task == null) { throw new IllegalStateException("Achievement unavailable"); }
				int id = task.getIntValue(TASK_ID);
				int encounterId = task.getIntValue(TASK_BOSS);
				String name = names.getStringValue(encounterId);
				if (name == null || name.isBlank() || name.equalsIgnoreCase("null") || name.equalsIgnoreCase("General")) { continue; }
				loaded.computeIfAbsent(name, ignored -> new ArrayList<>()).add(id);
				tiered.computeIfAbsent(encounterId, ignored -> new ArrayList<>())
					.add(new CaEncounter.Task(id, tier, task.getStringValue(1308)));
				encounterNames.put(encounterId, name);
			}
		}
		if (loaded.isEmpty()) { throw new IllegalStateException("Achievement catalogue unavailable"); }
		loaded.replaceAll((name, ids) -> List.copyOf(ids));
		List<CaEncounter> result = new ArrayList<>();
		tiered.forEach((id, values) -> result.add(new CaEncounter(id, encounterNames.get(id), values)));
		result.sort(java.util.Comparator.comparing(e -> e.name));
		encounters = List.copyOf(result);
		tasks.putAll(loaded);
		return java.util.Collections.unmodifiableMap(tasks);
	}

	static boolean isComplete(int flags, int bit)
	{
		return (flags & (1 << bit)) != 0;
	}
}

package com.wheelbound;

import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.game.ItemVariationMapping;

/** Probita's unlocked-pet bitmasks, including pets currently reclaimable. */
final class OwnedPets
{
    static final int PET_ITEMS = 985;

    static Set<Integer> read(Client client)
    {
        EnumComposition pets = client.getEnum(PET_ITEMS);
        if (pets == null || pets.getKeys() == null || pets.getKeys().length == 0)
        { throw new IllegalStateException("Pet data unavailable"); }
        int[] flags = {client.getVarpValue(VarPlayerID.PET_INSURANCE_BITMASK1),
            client.getVarpValue(VarPlayerID.PET_INSURANCE_BITMASK2),
            client.getVarpValue(VarPlayerID.PET_INSURANCE_BITMASK3)};
        Set<Integer> owned = new HashSet<>();
        for (int index : pets.getKeys())
        {
            if (index >= 0 && index < 93 && (flags[index / 31] & (1 << (index % 31))) != 0)
            { owned.add(ItemVariationMapping.map(pets.getIntValue(index))); }
        }
        return Set.copyOf(owned);
    }

    static boolean contains(Set<Integer> owned, PetDefinition pet)
    { return owned.contains(ItemVariationMapping.map(pet.itemId)); }
}

package com.wheelbound;

import java.util.List;
import java.util.Locale;

/** One wheel entry per CA encounter, never one wedge per task. */
final class CaEncounter
{
    enum Kind { MONSTER, BOSS, RAID }
    static final class Task
    {
        final int id;
        final CaTier tier;
        final String name;
        Task(int id, CaTier tier) { this(id, tier, null); }
        Task(int id, CaTier tier, String name)
        {
            this.id = id; this.tier = tier;
            this.name = name == null || name.isBlank() || name.equalsIgnoreCase("null")
                ? "Combat Achievement #" + id : name;
        }
    }
    final int id;
    final String name;
    final List<Task> tasks;
    final BossDefinition boss;
    final Kind kind;

    CaEncounter(int id, String name, List<Task> tasks)
    {
        this.id = id; this.name = name; this.tasks = List.copyOf(tasks);
        boss = BossCatalog.ALL.stream().filter(b -> b.caEncounters.stream()
            .anyMatch(alias -> normalize(alias).equals(normalize(name)))).findFirst().orElse(null);
        String normalized = normalize(name);
        boolean raid = normalized.startsWith("chambersofxeric") || normalized.startsWith("theatreofblood")
            || normalized.startsWith("tombsofamascut");
        kind = raid ? Kind.RAID : boss != null || normalized.equals("tzhaarketrakschallenges")
            ? Kind.BOSS : Kind.MONSTER;
    }
    static String normalize(String name)
    { return name.toLowerCase(Locale.ROOT).replaceFirst("^the\\s+", "").replaceAll("[^a-z0-9]", ""); }
}

package com.wheelbound;

import java.awt.*;
import java.util.Random;

/** Bounded, local celebration. Particle trajectories are analytic; no extra timer or thread. */
final class Confetti
{
    static final double DURATION_SECONDS = 3.0;
    private static final Color[] COLORS = {new Color(239, 190, 65), new Color(82, 201, 130),
        new Color(89, 173, 241), new Color(233, 101, 142), new Color(179, 130, 243)};
    private Confetti() {}

    static void paint(Graphics2D graphics, Rectangle bounds, double seconds)
    {
        if (seconds < 0 || seconds >= DURATION_SECONDS) { return; }
        Graphics2D g = (Graphics2D)graphics.create();
        g.clip(bounds);
        g.setComposite(AlphaComposite.SrcOver.derive((float)Math.min(1, (DURATION_SECONDS - seconds) / .8)));
        Random random = new Random(71263);
        for (int i = 0; i < 120; i++)
        {
            double direction = random.nextDouble() * Math.PI * 2;
            double speed = (90 + random.nextDouble() * 260) * Math.min(1, bounds.width / 650.0);
            double x = bounds.getCenterX() + Math.cos(direction) * speed * seconds;
            double y = bounds.getCenterY() - 50 + Math.sin(direction) * speed * seconds + 95 * seconds * seconds;
            Graphics2D particle = (Graphics2D)g.create();
            particle.translate(x, y); particle.rotate(direction + seconds * (i % 2 == 0 ? 5 : -5));
            particle.setColor(COLORS[i % COLORS.length]); particle.fillRect(-3, -5, 6, 10);
            particle.dispose();
        }
        g.dispose();
    }
}

package com.wheelbound;

