    private final JComboBox<Object> selector = new JComboBox<>();
    private CustomWheels customWheels;
    private CustomWheels.CustomWheel custom;
    private String customLoadError;
    private boolean rebuildingSelector;
    private final WheelNameDialog nameDialog = new WheelNameDialog();
    private final JPanel customEntryEditor = new JPanel(new BorderLayout(0, 5));
    private final JTextField entryName = new JTextField();
    private final JButton addEntry = new JButton("Add");
    private final JButton deleteWheel = new JButton("Delete wheel");
    private java.util.function.Predicate<String> confirmDelete = name -> JOptionPane.showConfirmDialog(this,
        html("Delete the custom wheel \"" + name + "\" and all its entries? This cannot be undone."),
        "Delete custom wheel", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE) == JOptionPane.YES_OPTION;
    private List<WheelEntry> availablePool = List.of();
    private String poolMessage = "";
    private WheelPopup popup;
    private WheelComponent displayed = wheel;
    private String popupTitle, popupResult;
    private final JPanel options = new JPanel(new CardLayout());
    private final List<AbstractButton> controls = new ArrayList<>();
    private final BiConsumer<String, Object> save;
    private final Gson gson;
    private final Random random = new Random();
    private Consumer<Boolean> action = ignored -> {};
    private Runnable refreshAction = () -> action.accept(false);
    private WheelType type;
    private boolean busy;
    private boolean sidebarActive;
    private long generation;
    private List<WheelEntry> deferred;
    private String deferredMessage;
    private WheelEntry questCompletion, deferredQuestCompletion;
    private boolean hasDeferredQuestCompletion;

    WheelboundPanel(Gson gson, Function<String, String> load, BiConsumer<String, Object> save)
    {
        super();
        this.gson = java.util.Objects.requireNonNull(gson);
        getScrollPane().setViewportView(this);
        this.save = save;
        type = WheelType.fromSaved(load.apply("selectedWheel"));
        loadCustomWheels(load);
        for (WheelType wheelType : WheelType.values())
        {
            BossChecklist checklist = new BossChecklist(wheelType == WheelType.CUSTOM ? "Included entries"
                : wheelType == WheelType.SKILLING ? "Included skills"
                : wheelType == WheelType.BOSSING ? "Included bosses"
                : wheelType == WheelType.QUESTING ? "Included quests"
                : wheelType == WheelType.PET_HUNTING ? "Included pets" : "Included encounters",
                (wheelType == WheelType.CUSTOM ? null : load.apply(wheelType.exclusionKey)), value -> {
                    if (wheelType == WheelType.CUSTOM) { customSelectionChanged(value); return; }
                    save.accept(wheelType.exclusionKey, value);
                    generation++;
                    popupResult = "Click the center to spin";
                    if (popup != null) { popup.clearResult(); }
                    updatePool(availablePool, poolMessage, generation);
                    refreshAction.run();
                }, wheelType == WheelType.CUSTOM ? this::deleteCustomEntry : null);
            checklists.put(wheelType, checklist);
            checklistCards.add(checklist, wheelType.name());
        }
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(BorderFactory.createEmptyBorder(10, 8, 10, 8));
        JPanel content = column();
        JLabel title = new JLabel(new ImageIcon(WheelStyle.headerImage()));
        title.setAlignmentX(Component.CENTER_ALIGNMENT);
        title.getAccessibleContext().setAccessibleName("Wheelbound - Spin your destiny");
        content.add(title);
        content.add(Box.createVerticalStrut(10));
        rebuildSelector();
        selector.setRenderer(new DefaultListCellRenderer() {
            @Override public Component getListCellRendererComponent(JList<?> list, Object value, int index,
                boolean selected, boolean focus)
            {
                super.getListCellRendererComponent(list, value == WheelType.CUSTOM ? "New custom wheel..." : value, index, selected, focus);
                putClientProperty("html.disable", Boolean.TRUE); return this;
            }
        });
        selector.setFont(FontManager.getDefaultBoldFont().deriveFont(12f));
        selector.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
        selector.setToolTipText("Choose a wheel");
        selector.setPrototypeDisplayValue("Combat Achievements");
        selector.setMinimumSize(new Dimension(0, 32));
        selector.addActionListener(e -> {
            if (rebuildingSelector) { return; }
            Object value = selector.getSelectedItem();
            if (value instanceof CustomWheels.CustomWheel) { selectCustomWheel(((CustomWheels.CustomWheel)value).id); }
            else if (value instanceof WheelType) { selectWheel((WheelType)value); }
        });
        content.add(selector);
        content.add(Box.createVerticalStrut(8));
        content.add(result);
        content.add(xpResult);
        content.add(Box.createVerticalStrut(10));
        options.setOpaque(false);
        for (WheelType wheelType : WheelType.values())
        {
            JPanel wheelOptions = column();
            String section = "";
            for (WheelFilter filter : WheelFilter.values())
            {
                if (filter.wheel != wheelType) { continue; }
                if (!section.equals(filter.section))
                {
                    section = filter.section;
                    wheelOptions.add(Box.createVerticalStrut(8));
                    JLabel heading = new JLabel(section);
                    heading.setForeground(ColorScheme.BRAND_ORANGE);
                    heading.setFont(FontManager.getDefaultBoldFont());
                    heading.setAlignmentX(Component.LEFT_ALIGNMENT);
                    wheelOptions.add(heading);
                }
                JCheckBox box = check(filter.title, filter.tip);
                String saved = filter.savedValue(load);
                // Migrate the two removed master options once through the new sidebar defaults.
                if (saved == null && filter == WheelFilter.ACCOUNT) { saved = load.apply("limitBossesToMyLevel"); }
                if (saved == null && filter == WheelFilter.MAXED_SKILLS) { saved = load.apply("excludeLevel99Skills"); }
                box.setSelected(saved == null ? filter.defaultValue : Boolean.parseBoolean(saved));
                box.addActionListener(e -> { save.accept(filter.key, box.isSelected()); filtersChanged(); });
                filters.put(filter, box); controls.add(box); wheelOptions.add(box);
            }
            options.add(wheelOptions, wheelType.name());
        }
        setupCustomControls();
        showCards();
        content.add(options);
        content.add(customEntryEditor);
        content.add(Box.createVerticalStrut(8));
        checklistCards.setOpaque(false);
        add(checklistCards, BorderLayout.CENTER);
        add(content, BorderLayout.NORTH);
        JPanel footer = new JPanel(new BorderLayout());
        footer.setOpaque(false);
        footer.setBorder(BorderFactory.createEmptyBorder(12, 0, 8, 0));
        status.setBorder(BorderFactory.createEmptyBorder(0, 8, 12, 8));
        footer.add(status, BorderLayout.CENTER);
        footer.add(deleteWheel, BorderLayout.SOUTH);
        getWrappedPanel().add(footer, BorderLayout.SOUTH);
        wheel.setSpinAction(() -> {
            if (busy) { return; }
            busy = true; enableControls(false); wheel.setAvailable(false);
            requestCurrent(true);
        });
        xpWheel.setAvailable(false);
        wheel.setFrameListener(this::refreshPopup);
        xpWheel.setFrameListener(this::refreshPopup);
        if (type == WheelType.CUSTOM) { bindCustomChecklist(); refreshCustomPool(false); }
    }

    @Override public Dimension getPreferredScrollableViewportSize() { return getPreferredSize(); }
    @Override public int getScrollableUnitIncrement(Rectangle visible, int orientation, int direction) { return 24; }
    @Override public int getScrollableBlockIncrement(Rectangle visible, int orientation, int direction)
    { return Math.max(24, visible.height - 24); }
    @Override public boolean getScrollableTracksViewportWidth() { return true; }
    @Override public boolean getScrollableTracksViewportHeight()
    { return getParent() instanceof JViewport && getParent().getHeight() >= getPreferredSize().height; }

    @Override public void onActivate()
    {
        sidebarActive = true;
        openWheel();
    }

    @Override public void onDeactivate()
    {
        sidebarActive = false;
        nameDialog.hide();
        if (popup != null) { popup.hide(); }
        generation++; wheel.cancel(); xpWheel.cancel(); finish();
    }

    void setPopup(WheelPopup value) { popup = value; }
    void setRefreshAction(Runnable value) { refreshAction = value; }
    WheelComponent primaryWheel() { return wheel; }
    WheelComponent secondaryWheel() { return xpWheel; }

    void selectWheel(WheelType value)
    {
        if (busy || value == null) { return; }
        if (type == value && custom == null)
        { if (value == WheelType.CUSTOM) { showNameDialog(); } return; }
        type = value; custom = null; selectionChanged();
    }

    void selectCustomWheel(String id)
    {
        CustomWheels.CustomWheel value = customWheels.find(id);
        if (busy || value == null || custom == value) { return; }
        custom = value; type = WheelType.CUSTOM; selectionChanged();
    }

    private void selectionChanged()
    {
        nameDialog.hide();
        entryName.setText("");
        save.accept("selectedWheel", type.title);
        save.accept("selectedCustomWheel", custom == null ? "" : custom.id);
        rebuildSelector(); showCards(); reset(); bindCustomChecklist(); requestCurrent(false);
        if (type == WheelType.CUSTOM && custom == null) { showNameDialog(); }
        else if (sidebarActive) { openWheel(); }
    }

    private void requestCurrent(boolean spin)
    { if (type == WheelType.CUSTOM) { refreshCustomPool(spin); } else { action.accept(spin); } }

    private String wheelTitle() { return custom == null ? type.title : custom.name; }

    private void setupCustomControls()
    {
        entryName.setName("customEntryName");
        entryName.getAccessibleContext().setAccessibleName("New entry");
        customEntryEditor.setOpaque(false);
        customEntryEditor.setBorder(BorderFactory.createEmptyBorder(10, 6, 12, 6));
        JLabel heading = new JLabel("New Entry"); heading.setLabelFor(entryName);
        customEntryEditor.add(heading, BorderLayout.NORTH);
        JPanel input = new JPanel(new BorderLayout(5, 0)); input.setOpaque(false);
        input.add(entryName, BorderLayout.CENTER); input.add(addEntry, BorderLayout.EAST);
        customEntryEditor.add(input, BorderLayout.CENTER);
        deleteWheel.setBackground(new Color(155, 45, 45)); deleteWheel.setForeground(Color.WHITE);
        deleteWheel.setOpaque(true);
        deleteWheel.setBorder(BorderFactory.createEmptyBorder(8, 5, 8, 5));
        deleteWheel.setToolTipText("Delete this custom wheel and all of its entries");
        controls.add(addEntry); controls.add(deleteWheel);
        addEntry.addActionListener(e -> addCustomEntry(entryName.getText()));
        entryName.addActionListener(e -> addCustomEntry(entryName.getText()));
        deleteWheel.addActionListener(e -> deleteSelectedCustomWheel());
        enableControls(true);
    }

    private void loadCustomWheels(Function<String, String> load)
    {
        customLoadError = null;
        try { customWheels = CustomWheels.load(gson, load.apply(CustomWheels.KEY)); }
        catch (IllegalArgumentException ex) { customLoadError = ex.getMessage(); customWheels = new CustomWheels(); }
        custom = type == WheelType.CUSTOM ? customWheels.find(load.apply("selectedCustomWheel")) : null;
    }

    private void rebuildSelector()
    {
        rebuildingSelector = true;
        try
        {
            selector.removeAllItems();
            for (WheelType value : WheelType.values()) { if (value != WheelType.CUSTOM) { selector.addItem(value); } }
            for (CustomWheels.CustomWheel value : customWheels.wheels()) { selector.addItem(value); }
            selector.addItem(WheelType.CUSTOM);
            selector.setSelectedItem(custom == null ? type : custom);
        }
        finally { rebuildingSelector = false; }
    }

    WheelNameDialog nameDialog() { return nameDialog; }

    private void showNameDialog()
    {
        if (busy) { return; }
        nameDialog.show(popup == null ? SwingUtilities.getWindowAncestor(this) : popup.creationAnchor(this), name -> {
            if (customLoadError != null) { return customLoadError; }
            return createCustomWheel(name);
        });
    }

    String createCustomWheel(String name)
    {
        if (busy || customLoadError != null || type != WheelType.CUSTOM || custom != null)
        { return customLoadError == null ? "Select New custom wheel to create a wheel." : customLoadError; }
        try
        {
            CustomWheels.CustomWheel created = customWheels.create(name);
            save.accept(CustomWheels.KEY, customWheels.save(gson));
            nameDialog.hide(); selectCustomWheel(created.id); entryName.requestFocusInWindow();
            return null;
        }
        catch (IllegalArgumentException ex) { status.setText(html(ex.getMessage())); return ex.getMessage(); }
    }

    void addCustomEntry(String name)
    {
        if (busy || custom == null) { return; }
        try
        {
            customWheels.add(custom, name); entryName.setText("");
            customEdited(); entryName.requestFocusInWindow();
        }
        catch (IllegalArgumentException ex) { status.setText(html(ex.getMessage())); }
    }

    private void customSelectionChanged(String excluded)
    {
        if (busy || custom == null) { return; }
        Set<String> ids = new java.util.HashSet<>(java.util.Arrays.asList(excluded.split(",")));
        custom.items.forEach(item -> item.enabled = !ids.contains("CUSTOM_" + item.id));
        customEdited();
    }

    private void deleteCustomEntry(WheelEntry entry)
    {
        if (busy || custom == null) { return; }
        custom.items.removeIf(item -> entry.id.equals("CUSTOM_" + item.id));
        customEdited();
    }

    private void customEdited()
    {
        save.accept(CustomWheels.KEY, customWheels.save(gson));
        generation++; bindCustomChecklist();
        result.setText(html("Spin the wheel")); result.setIcon(null); xpResult.setText("");
        if (popup != null) { popup.clearResult(); }
        refreshCustomPool(false);
    }

    private void bindCustomChecklist()
    { checklists.get(WheelType.CUSTOM).restore(custom == null ? null : custom.exclusions()); }

    void refreshCustomPool(boolean spin)
    {
        if (type != WheelType.CUSTOM) { return; }
        List<WheelEntry> entries = custom == null ? List.of() : custom.entries();
        String message = customLoadError != null ? customLoadError : custom == null
            ? "Name your custom wheel and click Create." : "Add entries above to build your wheel.";
        if (spin) { spinResponse(entries, message, generation); }
        else { updatePool(entries, message, generation); }
    }

    void setDeleteConfirmation(java.util.function.Predicate<String> confirmation) { confirmDelete = confirmation; }

    void deleteSelectedCustomWheel()
    {
        if (busy || custom == null) { return; }
        CustomWheels.CustomWheel target = custom;
        CustomWheels store = customWheels;
        if (!confirmDelete.test(target.name) || busy || custom != target || customWheels != store) { return; }
        customWheels.remove(target); save.accept(CustomWheels.KEY, customWheels.save(gson));
        custom = null;
        if (customWheels.wheels().isEmpty()) { type = WheelType.BOSSING; }
        else { custom = customWheels.wheels().get(0); type = WheelType.CUSTOM; }
        selectionChanged();
    }

    private void showCards()
    {
        customEntryEditor.setVisible(type == WheelType.CUSTOM && custom != null);
        deleteWheel.setVisible(type == WheelType.CUSTOM && custom != null);
        ((CardLayout)options.getLayout()).show(options, type.name());
        ((CardLayout)checklistCards.getLayout()).show(checklistCards, type.name());
        for (Component card : options.getComponents())
        {
            if (card.isVisible())
            {
                card.invalidate();
                Dimension size = card.getPreferredSize();
                options.setPreferredSize(size);
                options.setMinimumSize(new Dimension(0, size.height));
                options.setMaximumSize(new Dimension(Integer.MAX_VALUE, size.height));
            }
        }
        if (options.getParent() != null) { options.getParent().invalidate(); }
        invalidate();
        revalidate();
    }
    private BossChecklist checklist() { return checklists.get(type); }
    boolean selected(WheelFilter filter) { return filters.get(filter).isSelected(); }
    void reloadPreferences(Function<String, String> load)
    {
        nameDialog.hide();
        entryName.setText("");
        filters.forEach((filter, box) -> {
            String value = filter.savedValue(load);
            if (value == null && filter == WheelFilter.ACCOUNT) { value = load.apply("limitBossesToMyLevel"); }
            if (value == null && filter == WheelFilter.MAXED_SKILLS) { value = load.apply("excludeLevel99Skills"); }
            box.setSelected(value == null ? filter.defaultValue : Boolean.parseBoolean(value));
        });
        checklists.forEach((wheelType, checklist) -> checklist.restore(wheelType == WheelType.CUSTOM ? null : load.apply(wheelType.exclusionKey)));
        type = WheelType.fromSaved(load.apply("selectedWheel")); loadCustomWheels(load);
        rebuildSelector(); showCards(); reset(); bindCustomChecklist();
        if (type == WheelType.CUSTOM) { refreshCustomPool(false); }
    }
    Set<WheelFilter> selectedFilters()
    {
        Set<WheelFilter> result = EnumSet.noneOf(WheelFilter.class);
        filters.forEach((filter, box) -> { if (box.isSelected()) { result.add(filter); } });
        return Set.copyOf(result);
    }

    void openWheel()
    {
        if (type == WheelType.CUSTOM && custom == null) { showNameDialog(); return; }
        if (popup == null || busy || popup.isOpen()) { return; }
        displayed = wheel; popupTitle = wheelTitle(); popupResult = "Click the center to spin";
        popup.show(popupTitle, displayed, popupResult, () -> displayed.requestSpin(), () -> {
            generation++;
            wheel.cancel(); xpWheel.cancel();
            if (busy) { result.setText(html("Spin cancelled")); xpResult.setText(""); }
            finish();
        });
        if (questCompletion != null) { popup.complete(questCompletion, QuestPool.COMPLETE); }
    }

    void setQuestCompletion(WheelEntry entry)
    {
        if (type != WheelType.QUESTING) { return; }
        if (busy) { deferredQuestCompletion = entry; hasDeferredQuestCompletion = true; return; }
        boolean hadCompletion = questCompletion != null;
        questCompletion = entry;
        if (entry != null)
        {
            result.setText(html(QuestPool.COMPLETE));
            result.setIcon(entry.icon == null ? null : new ImageIcon(entry.icon));
            if (popup != null && !popup.hasResult()) { popup.complete(entry, QuestPool.COMPLETE); }
        }
        else if (hadCompletion)
        {
            result.setText(html("Spin the wheel")); result.setIcon(null);
            if (popup != null) { popup.clearResult(); }
        }
    }

    private void refreshPopup()
    {
        if (popup != null) { popup.update(popupTitle, displayed, popupResult); }
    }
    private void filtersChanged()
    {
        generation++; wheel.setAvailable(false);
        if (popup != null) { popup.clearResult(); }
        refreshAction.run();
    }
    void setAction(Consumer<Boolean> value) { action = value; }
    WheelType wheelType() { return type; }
    long generation() { return generation; }
    boolean busy() { return busy; }

    void updatePool(List<WheelEntry> entries, String message, long revision)
    {
        if (revision != generation) { return; }
        if (busy) { deferred = entries; deferredMessage = message; return; }
        availablePool = List.copyOf(entries); poolMessage = message;
        checklist().updateEntries(entries);
        List<WheelEntry> included = checklist().included(entries);
        displayed = wheel; popupTitle = wheelTitle();
        wheel.setEntries(included); wheel.setAvailable(!included.isEmpty());
        status.setToolTipText(message);
        status.setText(html(!entries.isEmpty()
            ? included.size() + " of " + entries.size() + " eligible entries included."
                + (included.isEmpty() ? " Check an entry above to spin." : "")
                + (type == WheelType.COMBAT_ACHIEVEMENTS ? " Unfinished tasks only." : "")
            : message));
    }

    void spinResponse(List<WheelEntry> entries, String message, long revision)
    {
        if (revision != generation) { return; }
        List<WheelEntry> choices = checklist().included(entries);
        if (choices.isEmpty()) { finish(); updatePool(entries, message, revision); return; }
        int selected = WheelSelection.select(choices, random);
        displayed = wheel; popupTitle = wheelTitle(); popupResult = "Spinning...";
        if (popup != null) { popup.clearResult(); }
        result.setIcon(null); result.setText(html("Spinning...")); xpResult.setText("");
        boolean withXp = type == WheelType.SKILLING && selected(WheelFilter.XP);
        String achievement = type == WheelType.COMBAT_ACHIEVEMENTS && selected(WheelFilter.CA_SPECIFIC)
            ? choices.get(selected).pickAchievement(random) : null;
        wheel.animate(choices, selected, () -> {
            popupResult = choices.get(selected).label;
            result.setText(html(popupResult));
            if (choices.get(selected).icon != null)
            {
                result.setIcon(new ImageIcon(net.runelite.client.util.ImageUtil.resizeImage(choices.get(selected).icon, 48, 48)));
                result.setHorizontalTextPosition(SwingConstants.CENTER);
                result.setVerticalTextPosition(SwingConstants.BOTTOM);
            }
            if (choices.get(selected).source != null) { xpResult.setText(html(choices.get(selected).source)); }
            if (achievement != null) { xpResult.setText(html(achievement)); }
            if (withXp)
            {
                xpResult.setText(html("Click SPIN to choose your XP target")); revalidate();
                displayed = xpWheel; popupTitle = choices.get(selected).label + " - XP target";
                List<WheelEntry> goals = XpGoal.entries();
                xpWheel.setEntries(goals);
                xpWheel.setSpinAction(() -> {
                    xpWheel.setAvailable(false);
                    xpResult.setText(html("Choosing an XP target..."));
                    int goal = WheelSelection.select(goals, random);
                    xpWheel.animate(goals, goal, () -> {
                        popupResult = choices.get(selected).label + " - " + goals.get(goal).label;
                        xpResult.setText(html(goals.get(goal).label));
                        finish();
                        if (popup != null) { popup.complete(choices.get(selected), goals.get(goal).label); }
                    });
                });
                xpWheel.setAvailable(true);

            }
            else
            {
                finish();
                if (popup != null)
                { popup.complete(questCompletion != null ? questCompletion : choices.get(selected),
                    questCompletion != null ? QuestPool.COMPLETE : achievement); }
            }
        });
        revalidate();
    }

    private void finish()
    {
        xpWheel.setAvailable(false);
        busy = false; enableControls(true); wheel.setAvailable(!wheel.entries().isEmpty());
        displayed = wheel; popupTitle = wheelTitle(); refreshPopup();
        if (deferred != null)
        {
            List<WheelEntry> entries = deferred; deferred = null;
            updatePool(entries, deferredMessage, generation);
        }
        if (hasDeferredQuestCompletion)
        {
            hasDeferredQuestCompletion = false;
            setQuestCompletion(deferredQuestCompletion); deferredQuestCompletion = null;
        }
    }
    private void enableControls(boolean enabled)
    {
        controls.forEach(c -> c.setEnabled(enabled)); selector.setEnabled(enabled);
        checklists.values().forEach(c -> c.setEnabled(enabled));
        entryName.setEnabled(enabled && custom != null);
        addEntry.setEnabled(enabled && custom != null); deleteWheel.setEnabled(enabled && custom != null);
    }
    void reset()
    {
        nameDialog.hide();
        if (popup != null) { popup.hide(); }
        generation++; wheel.cancel(); xpWheel.cancel(); busy = false; deferred = null; questCompletion = null; deferredQuestCompletion = null; hasDeferredQuestCompletion = false;
        displayed = wheel; popupTitle = wheelTitle(); availablePool = List.of();
        checklist().updateEntries(List.of()); status.setText(html("Loading eligible entries..."));
        wheel.setEntries(List.of());
        result.setIcon(null); result.setText(html("Spin the wheel")); xpResult.setText("");
        enableControls(true); revalidate();
    }
    private static JPanel column()
    {
        JPanel panel = new JPanel(); panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setOpaque(false); panel.setAlignmentX(Component.CENTER_ALIGNMENT); return panel;
    }
    private static JCheckBox check(String text, String tip)
    {
        JCheckBox box = new JCheckBox(text); box.setOpaque(false);
        box.setFont(FontManager.getDefaultFont().deriveFont(12f)); box.setForeground(ColorScheme.TEXT_COLOR);
        box.setIconTextGap(7); box.setBorder(BorderFactory.createEmptyBorder(5, 0, 5, 0));
        box.setToolTipText(tip); box.setAlignmentX(Component.LEFT_ALIGNMENT); return box;
    }
    private static JLabel label(String text, boolean strong)
    {
        JLabel label = new JLabel(html(text), SwingConstants.CENTER);
        label.setForeground(strong ? ColorScheme.BRAND_ORANGE : ColorScheme.LIGHT_GRAY_COLOR);
        label.setFont(strong ? FontManager.getRunescapeBoldFont() : FontManager.getDefaultFont().deriveFont(12f));
        label.setAlignmentX(Component.CENTER_ALIGNMENT); return label;
    }
    private static String html(String text) { return "<html><div style='width:145px;text-align:center'>" + BossChecklist.escape(text) + "</div></html>"; }
}

package com.wheelbound;

import java.awt.image.BufferedImage;
import java.util.Objects;

/** Immutable presentation entry; the same weight drives selection and wedge geometry. */
final class WheelEntry
{
    final String id;
    final String label;
    final BufferedImage icon;
    final int weight;
    final String source;
    final BufferedImage sourceIcon;
    final java.util.List<CaEncounter.Task> tasks;

    WheelEntry(String id, String label, BufferedImage icon, int weight)
    {
        this(id, label, icon, weight, null, null);
    }

    WheelEntry(String id, String label, BufferedImage icon, int weight, String source, BufferedImage sourceIcon)
    {
        this(id, label, icon, weight, source, sourceIcon, java.util.List.of());
    }

    private WheelEntry(String id, String label, BufferedImage icon, int weight, String source,
        BufferedImage sourceIcon, java.util.List<CaEncounter.Task> tasks)
    {
        this.tasks = java.util.List.copyOf(tasks);
        this.source = source; this.sourceIcon = sourceIcon;
        if (weight <= 0) { throw new IllegalArgumentException("Weight must be positive"); }
        this.id = Objects.requireNonNull(id);
        this.label = Objects.requireNonNull(label);
        this.icon = icon;
        this.weight = weight;
    }

    WheelEntry withTasks(java.util.List<CaEncounter.Task> tasks)
    { return new WheelEntry(id, label, icon, weight, source, sourceIcon, tasks); }

    String pickAchievement(java.util.Random random)
    {
        if (tasks.isEmpty()) { return null; }
        CaEncounter.Task task = tasks.get(random.nextInt(tasks.size()));
        return task.name + " (" + task.tier.title + ")";
    }

    /** Presentation grouping happens after mode-specific eligibility and CA task filtering. */
    static java.util.List<WheelEntry> groupRaids(java.util.List<WheelEntry> entries)
    {
        java.util.Map<String, WheelEntry> grouped = new java.util.LinkedHashMap<>();
        for (WheelEntry entry : entries)
        {
            String name = entry.label;
            for (String raid : java.util.List.of("Chambers of Xeric", "Theatre of Blood", "Tombs of Amascut"))
            {
                if (name.startsWith(raid)) { name = raid; break; }
            }
            String id = name.equals("Chambers of Xeric") ? "CHAMBERS_OF_XERIC"
                : name.equals("Theatre of Blood") ? "THEATRE_OF_BLOOD"
                : name.equals("Tombs of Amascut") ? "TOMBS_OF_AMASCUT" : entry.id;
            WheelEntry previous = grouped.get(id);
            if (previous == null && id.equals(entry.id) && name.equals(entry.label))
            {
                grouped.put(id, entry);
                continue;
            }
            java.util.Map<Integer, CaEncounter.Task> tasks = new java.util.LinkedHashMap<>();
            if (previous != null) { previous.tasks.forEach(task -> tasks.put(task.id, task)); }
            entry.tasks.forEach(task -> tasks.putIfAbsent(task.id, task));
            WheelEntry base = previous != null ? previous : new WheelEntry(id, name, entry.icon,
                entry.weight, entry.source, entry.sourceIcon);
            grouped.put(id, base.withTasks(java.util.List.copyOf(tasks.values())));
        }
        return java.util.List.copyOf(grouped.values());
    }

    String wheelLabel()
    {
        if (id.startsWith("CUSTOM_")) { return label; }
        switch (label)
        {
            case "Chambers of Xeric": return "CoX";
            case "Theatre of Blood": return "ToB";
            case "Tombs of Amascut": return "ToA";
            case "Dagannoth Supreme": return "DK Supreme";
            case "Dagannoth Prime": return "DK Prime";
            case "Dagannoth Rex": return "DK Rex";
            case "The Corrupted Gauntlet": return "Corrupted G.";
            case "Thermonuclear Smoke Devil": return "Thermy";
            case "Grotesque Guardians": return "Guardians";
            case "Phantom Muspah": return "Muspah";
            case "Alchemical Hydra": return "Hydra";
            case "Phosani's Nightmare": return "Phosani";
            case "Corporeal Beast": return "Corp";
            case "Commander Zilyana": return "Zilyana";
            case "General Graardor": return "Graardor";
            case "Chaos Elemental": return "Chaos Ele";
            case "Chaos Fanatic": return "Fanatic";
            case "Crazy Archaeologist": return "Crazy Arch.";
            case "Deranged Archaeologist": return "Deranged A.";
            case "The Royal Titans": return "Royal Titans";
            case "Doom of Mokhaiotl": return "Doom";
            case "Shellbane Gryphon": return "Gryphon";
            default: return label.startsWith("The ") ? label.substring(4) : label;
        }
    }
}

package com.wheelbound;

/** Sidebar wheel registry. Each wheel owns its options and manual exclusions. */
enum WheelType
{
    BOSSING("Bossing", "excludedBosses"),
    SKILLING("Skilling", "excludedSkills"),
    COMBAT_ACHIEVEMENTS("Combat Achievements", "excludedCaEncounters"),
    QUESTING("Questing", "excludedQuests"),
    PET_HUNTING("Pet Hunting", "excludedPets"),
    CUSTOM("Custom", "excludedCustomEntries");

    final String title, exclusionKey;
    WheelType(String title, String exclusionKey) { this.title = title; this.exclusionKey = exclusionKey; }
    static WheelType fromSaved(String value)
    {
        for (WheelType type : values()) { if (type.title.equals(value)) { return type; } }
        return BOSSING;
    }
    @Override public String toString() { return title; }
}

package com.wheelbound;

import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.util.function.Function;
import javax.swing.*;

/** EDT-only name form. Native Swing input retains caret, selection, paste and accessibility. */
final class WheelNameDialog
{
    private final JPanel content = new JPanel(new BorderLayout(0, 14)) {
        @Override protected void paintComponent(Graphics graphics)
        {
            Graphics2D g = (Graphics2D)graphics.create();
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setPaint(new GradientPaint(0, 0, new Color(28, 31, 32), getWidth(), getHeight(), new Color(19, 22, 23)));
            g.fillRoundRect(0, 0, getWidth(), getHeight(), 18, 18);
            g.setColor(WheelStyle.GOLD.darker());
            g.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 18, 18); g.dispose();
        }
    };
    private final JTextField name = new JTextField();
    private final JLabel error = new JLabel(" ");
    private JDialog window;
    private boolean open;
    private Function<String, String> submit = ignored -> null;

    WheelNameDialog()
    {
        content.setBorder(BorderFactory.createEmptyBorder(18, 24, 22, 24));
        content.setPreferredSize(new Dimension(380, 245));
        JPanel header = new JPanel(new BorderLayout()); header.setOpaque(false);
        JLabel title = new JLabel("New custom wheel", SwingConstants.CENTER);
        title.setFont(new Font(Font.SERIF, Font.BOLD, 24)); title.setForeground(WheelStyle.GOLD);
        // Keep the close glyph ASCII-encoded to survive Windows text tooling.
        //noinspection UnnecessaryUnicodeEscape
        JButton close = new JButton("\u00d7"); close.setForeground(WheelStyle.GOLD);
        close.setContentAreaFilled(false); close.setBorderPainted(false);
        close.setToolTipText("Cancel"); close.getAccessibleContext().setAccessibleName("Cancel creation");
        close.addActionListener(e -> hide());
        header.add(title, BorderLayout.CENTER); header.add(close, BorderLayout.EAST);
        content.add(header, BorderLayout.NORTH);
        JPanel fields = new JPanel(new BorderLayout(0, 8)); fields.setOpaque(false);
        JLabel label = new JLabel("Wheel name"); label.setForeground(new Color(225, 221, 207)); label.setLabelFor(name);
        name.setName("customWheelName"); name.getAccessibleContext().setAccessibleName("Wheel name");
        name.setBackground(new Color(35, 38, 39)); name.setForeground(Color.WHITE); name.setCaretColor(WheelStyle.GOLD);
        name.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(WheelStyle.GOLD.darker()),
            BorderFactory.createEmptyBorder(8, 8, 8, 8)));
        error.setForeground(new Color(240, 130, 130));
        fields.add(label, BorderLayout.NORTH); fields.add(name, BorderLayout.CENTER); fields.add(error, BorderLayout.SOUTH);
        content.add(fields, BorderLayout.CENTER);
        JButton create = new JButton("Create");
        create.setBackground(new Color(42, 133, 65)); create.setForeground(Color.WHITE); create.setOpaque(true);
        create.setBorder(BorderFactory.createEmptyBorder(10, 12, 10, 12));
        content.add(create, BorderLayout.SOUTH);
        create.addActionListener(e -> submit()); name.addActionListener(e -> submit());
        content.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW).put(KeyStroke.getKeyStroke("ESCAPE"), "cancel");
        content.getActionMap().put("cancel", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent event) { hide(); }
        });
    }

    void show(Component anchor, Function<String, String> action)
    {
        if (open) { if (window != null) { window.toFront(); } return; }
        submit = action; name.setText(""); error.setText(" "); open = true;
        // Tests can exercise the exact form without creating native windows.
        if (anchor == null || !anchor.isShowing() || GraphicsEnvironment.isHeadless()) { return; }
        window = new JDialog(SwingUtilities.getWindowAncestor(anchor), "New custom wheel", Dialog.ModalityType.MODELESS);
        window.setUndecorated(true); window.setResizable(false); window.setContentPane(content);
        window.setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);
        window.addWindowListener(new WindowAdapter() {
            @Override public void windowClosing(WindowEvent event) { hide(); }
        });
        window.pack(); window.setLocationRelativeTo(anchor); window.setVisible(true);
        name.requestFocusInWindow();
    }

    private void submit()
    {
        if (!open) { return; }
        String message = submit.apply(name.getText());
        if (message != null)
        { error.setText("<html>" + BossChecklist.escape(message) + "</html>"); name.requestFocusInWindow(); }
    }

    void hide()
    { open = false; submit = ignored -> null; if (window != null) { window.dispose(); window = null; } }
    boolean isOpen() { return open; }
    JPanel content() { return content; }
}

package com.wheelbound;

import java.awt.*;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseWheelListener;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Centered game-canvas popup. Only immutable wheel snapshots cross from Swing to rendering. */
@Singleton
public class WheelPopup extends Overlay implements KeyListener
{
    private final Client client;
    private volatile View view;
    private volatile Result selectedResult;
    private volatile Layout bounds;
    private volatile Runnable spin = () -> {}, dismiss = () -> {};
    private final AtomicLong generation = new AtomicLong();
    private volatile boolean hover, pressed;
    private boolean consumeClick;

    @Inject WheelPopup(Client client)
    {
        this.client = client;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
        setPriority(PRIORITY_HIGHEST);
        setMovable(false);
    }

    static final class View
    {
        final String title, result;
        final List<WheelEntry> entries;
        final double angle;
        final boolean available, busy;
        View(String title, List<WheelEntry> entries, double angle, String result, boolean available, boolean busy)
        {
            this.title = title; this.entries = List.copyOf(entries); this.angle = angle;
            this.result = result; this.available = available; this.busy = busy;
        }
    }

    private static final class Result
    {
        final WheelEntry entry;
        final String detail;
        final long started = System.nanoTime();
        Result(WheelEntry entry, String detail) { this.entry = entry; this.detail = detail; }
    }

    void complete(WheelEntry entry, String detail)
    {
        if (view != null) { selectedResult = new Result(entry, detail); }
    }
    void clearResult() { selectedResult = null; }
    boolean hasResult() { return selectedResult != null; }
    int entryCount() { View current = view; return current == null ? 0 : current.entries.size(); }

    static final class Layout
    {
        final Rectangle card, wheel, close, results;
        Layout(int width, int height)
        {
            int w = Math.max(160, Math.min(740, width - 24));
            int h = Math.max(200, Math.min(820, height - 24));
            card = new Rectangle((width - w) / 2, (height - h) / 2, w, h);
            int size = Math.max(80, Math.min(w - 28, h - 184));
            wheel = new Rectangle((width - size) / 2, card.y + 78, size, size);
            results = new Rectangle(card.x + 20, wheel.y + size + 18, w - 40, 64);
            close = new Rectangle(card.x + w - 36, card.y + 8, 28, 28);
        }
        boolean hub(Point point)
        {
            return point.distance(wheel.getCenterX(), wheel.getCenterY()) <= WheelStyle.hubSize(wheel.width - 24) / 2.0;
        }
    }

    void show(String title, WheelComponent wheel, String result, Runnable onSpin, Runnable onDismiss)
    {
        generation.incrementAndGet(); spin = onSpin; dismiss = onDismiss; hover = false; pressed = false; mousePoint = null;
        selectedResult = null;
        view = snapshot(title, wheel, result);
    }

    void update(String title, WheelComponent wheel, String result)
    {
        if (view != null) { view = snapshot(title, wheel, result); }
    }

    private static View snapshot(String title, WheelComponent wheel, String result)
    {
        return new View(title, wheel.entries(), wheel.angle(), result, wheel.canSpin(), wheel.busy());
    }

    void hide() { generation.incrementAndGet(); view = null; selectedResult = null; hover = false; pressed = false; }
    boolean isOpen() { return view != null; }
    Component creationAnchor(Component fallback) { return client == null ? fallback : client.getCanvas(); }

    private void close()
    {
        Runnable callback = dismiss;
        hide();
        long epoch = generation.get();
        SwingUtilities.invokeLater(() -> { if (generation.get() == epoch) { callback.run(); } });
    }

    private void requestSpin()
    {
        View current = view;
        if (current == null || !current.available || current.busy) { return; }
        long epoch = generation.get();
        SwingUtilities.invokeLater(() -> { if (view != null && generation.get() == epoch) { spin.run(); } });
    }

    @Override public Dimension render(Graphics2D graphics)
    {
        View current = view;
        if (current == null) { return null; }
        Result result = selectedResult;
        bounds = paint(graphics, client.getCanvasWidth(), client.getCanvasHeight(), current, hover, pressed);
        if (result != null)
        {
            paintResultRow(graphics, bounds, result.entry, result.detail);
            Graphics2D celebration = (Graphics2D)graphics.create();
            Confetti.paint(celebration, bounds.card, (System.nanoTime() - result.started) / 1_000_000_000.0);
            celebration.dispose();
        }
        Point point = mousePoint;
        if (point != null && bounds.wheel.contains(point) && !bounds.hub(point) && !current.busy)
        {
            double dx = point.x - bounds.wheel.getCenterX(), dy = bounds.wheel.getCenterY() - point.y;
            double degrees = ((Math.toDegrees(Math.atan2(dy, dx)) + current.angle) % 360 + 360) % 360;
            int index = WheelSelection.indexAt(current.entries, degrees / 360 * WheelSelection.totalWeight(current.entries));
            if (index >= 0 && Math.hypot(dx, dy) <= (bounds.wheel.width - 24) / 2.0)
            {
                Graphics2D g = (Graphics2D)graphics.create();
                g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 12));
                WheelEntry entry = current.entries.get(index);
                String tip = entry.label + String.format(java.util.Locale.US, " (%.1f%%)",
                    entry.weight * 100.0 / WheelSelection.totalWeight(current.entries));
                int w = g.getFontMetrics().stringWidth(tip) + 16;
                int x = Math.max(0, Math.min(point.x + 12, client.getCanvasWidth() - w));
                int y = Math.min(point.y + 20, client.getCanvasHeight() - 25);
                g.setColor(new Color(19, 22, 23, 240)); g.fillRoundRect(x, y, w, 24, 6, 6);
                g.setColor(WheelStyle.GOLD); g.drawString(tip, x + 8, y + 17);
                g.dispose();
            }
        }
        return null;
    }

    static Layout paint(Graphics2D graphics, int width, int height, View current, boolean hover, boolean pressed)
    {
        Layout layout = new Layout(width, height);
        Rectangle card = layout.card, wheel = layout.wheel;
        Graphics2D g = (Graphics2D)graphics.create();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(new Color(0, 0, 0, 155)); g.fillRect(0, 0, width, height);
        g.setPaint(new GradientPaint(card.x, card.y, new Color(28, 31, 32),
            card.x + card.width, card.y + card.height, new Color(19, 22, 23)));
        g.fillRoundRect(card.x, card.y, card.width, card.height, 18, 18);
        g.setColor(WheelStyle.GOLD.darker()); g.drawRoundRect(card.x, card.y, card.width, card.height, 18, 18);
        g.setColor(WheelStyle.GOLD); g.setFont(new Font(Font.SERIF, Font.BOLD, 27));
        WheelStyle.centered(g, "Wheelbound", width / 2, card.y + 34);
        g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 13)); g.setColor(new Color(225, 221, 207));
        WheelStyle.centered(g, fitText(g.getFontMetrics(), current.title, card.width - 40), width / 2, card.y + 60);
        g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 22));
        // Keep the close glyph ASCII-encoded to survive Windows text tooling.
        //noinspection UnnecessaryUnicodeEscape
        g.drawString("\u00d7", layout.close.x + 6, layout.close.y + 22);
        Graphics2D wg = (Graphics2D)g.create(wheel.x, wheel.y, wheel.width, wheel.height);
        WheelStyle.drawWheel(wg, wheel.width, wheel.height, current.entries, current.angle,
            current.available, hover, pressed, current.busy);
        wg.dispose();
        g.dispose();
        return layout;
    }

    static Rectangle paintResultRow(Graphics2D graphics, Layout layout, WheelEntry entry, String detail)
    {
        if (entry == null) { return null; }
        Graphics2D g = (Graphics2D)graphics.create();
        boolean custom = entry.id.startsWith("CUSTOM_");
        int padding = custom ? 28 : 80;
        Font nameFont = new Font(Font.SERIF, Font.BOLD, 20);
        while (g.getFontMetrics(nameFont).stringWidth(entry.label) > layout.results.width - padding && nameFont.getSize() > 10)
        { nameFont = nameFont.deriveFont((float)nameFont.getSize() - 1); }
        String subtitle = entry.source != null ? entry.source : detail;
        int sourceIconSpace = entry.source != null ? 24 : 0;
        Font detailFont = new Font(Font.SANS_SERIF, Font.PLAIN, 12);
        while (subtitle != null && g.getFontMetrics(detailFont).stringWidth(subtitle) + sourceIconSpace > layout.results.width - padding
            && detailFont.getSize() > 8)
        { detailFont = detailFont.deriveFont((float)detailFont.getSize() - 1); }
        int textWidth = g.getFontMetrics(nameFont).stringWidth(entry.label);
        if (subtitle != null)
        { textWidth = Math.max(textWidth, g.getFontMetrics(detailFont).stringWidth(subtitle) + sourceIconSpace); }
        int boxWidth = Math.min(layout.results.width, textWidth + padding);
        Rectangle box = new Rectangle((int)layout.card.getCenterX() - boxWidth / 2,
            layout.results.y, boxWidth, layout.results.height);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(new Color(35, 38, 39));
        g.fillRoundRect(box.x, box.y, box.width, box.height, 10, 10);
        g.setColor(WheelStyle.GOLD.darker());
        g.drawRoundRect(box.x, box.y, box.width, box.height, 10, 10);
        int iconSize = 40;
        int textX = box.x + (custom ? 14 : 66);
        g.setColor(WheelStyle.GOLD);
        java.awt.image.BufferedImage resultIcon = custom ? null : entry.icon;
        if (resultIcon != null)
        {
            double scale = Math.min((double)iconSize / resultIcon.getWidth(), (double)iconSize / resultIcon.getHeight());
            int iw = (int)Math.round(resultIcon.getWidth() * scale), ih = (int)Math.round(resultIcon.getHeight() * scale);
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
            g.drawImage(resultIcon, box.x + 14 + (iconSize - iw) / 2, box.y + (box.height - ih) / 2, iw, ih, null);
        }
        else if (!custom)
        {
            g.setFont(new Font(Font.SERIF, Font.BOLD, 26));
            WheelStyle.centered(g, entry.label.substring(0, 1), box.x + 34, box.y + 41);
        }
        g.setFont(nameFont);
        g.drawString(fitText(g.getFontMetrics(), entry.label, box.x + box.width - textX - 12), textX, box.y + (subtitle == null ? 39 : 27));
        if (subtitle != null)
        {
            if (entry.source != null)
            {
                if (entry.sourceIcon != null)
                {
                    double scale = Math.min(18.0 / entry.sourceIcon.getWidth(), 18.0 / entry.sourceIcon.getHeight());
                    int iw = (int)Math.round(entry.sourceIcon.getWidth() * scale);
                    int ih = (int)Math.round(entry.sourceIcon.getHeight() * scale);
                    g.drawImage(entry.sourceIcon, textX + (18 - iw) / 2, box.y + 34 + (18 - ih) / 2, iw, ih, null);
                }
                else
                {
                    g.setFont(detailFont);
                    g.drawRoundRect(textX, box.y + 34, 18, 18, 4, 4);
                    WheelStyle.centered(g, entry.source.substring(0, 1), textX + 9, box.y + 47);
                }
            }
            g.setFont(detailFont);
            g.setColor(new Color(225, 221, 207));
            g.drawString(fitText(g.getFontMetrics(), subtitle,
                box.x + box.width - textX - sourceIconSpace - 12), textX + sourceIconSpace, box.y + 47);
        }
        g.dispose();
        return box;
    }

    private static String fitText(FontMetrics metrics, String text, int width)
    {
        if (metrics.stringWidth(text) <= width) { return text; }
        int end = text.length();
        while (end > 0 && metrics.stringWidth(text.substring(0, end) + "?") > width)
        { end = text.offsetByCodePoints(end, -1); }
        return text.substring(0, end) + "?";
    }

    private volatile Point mousePoint;
    private void move(MouseEvent event)
    {
        mousePoint = event.getPoint();
        Layout layout = bounds;
        hover = layout != null && layout.hub(event.getPoint());
    }

    final MouseAdapter mouse = new MouseAdapter()
    {
        @Override public MouseEvent mousePressed(MouseEvent e)
        {
            consumeClick = isOpen();
            if (consumeClick)
            {
                e.consume(); move(e);
                Layout layout = bounds;
                if (e.getButton() == MouseEvent.BUTTON1 && layout != null)
                {
                    if (layout.close.contains(e.getPoint())) { close(); }
                    else { pressed = view != null && view.available && layout.hub(e.getPoint()); }
                }
            }
            return e;
        }
        @Override public MouseEvent mouseReleased(MouseEvent e)
        {
            if (isOpen() || consumeClick) { e.consume(); }
            if (pressed && e.getButton() == MouseEvent.BUTTON1 && bounds != null && bounds.hub(e.getPoint())) { requestSpin(); }
            pressed = false;
            return e;
        }
        @Override public MouseEvent mouseClicked(MouseEvent e)
        { if (isOpen() || consumeClick) { e.consume(); } consumeClick = false; return e; }
        @Override public MouseEvent mouseMoved(MouseEvent e)
        { if (isOpen()) { move(e); e.consume(); } return e; }
        @Override public MouseEvent mouseDragged(MouseEvent e)
        { if (isOpen() || consumeClick) { move(e); e.consume(); } return e; }
    };
    final MouseWheelListener mouseWheel = e -> { if (isOpen()) { e.consume(); } return e; };

    @Override public boolean isEnabledOnLoginScreen() { return true; }
    @Override public void keyPressed(KeyEvent event)
    {
        if (!isOpen() || typing(event)) { return; }
        event.consume();
        if (event.getKeyCode() == KeyEvent.VK_ESCAPE) { close(); }
        else if (event.getKeyCode() == KeyEvent.VK_SPACE || event.getKeyCode() == KeyEvent.VK_ENTER) { requestSpin(); }
    }
    @Override public void keyReleased(KeyEvent event) { if (isOpen() && !typing(event)) { event.consume(); } }
    @Override public void keyTyped(KeyEvent event) { if (isOpen() && !typing(event)) { event.consume(); } }

    private static boolean typing(KeyEvent event)
    {
        return event.getComponent() instanceof javax.swing.text.JTextComponent;
    }
}

package com.wheelbound;

import java.awt.*;
import java.awt.geom.Arc2D;
import java.awt.image.BufferedImage;
import java.util.List;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/** Custom wheel artwork within RuneLite's normal panel palette. */
final class WheelStyle
{
    static final Color GOLD = new Color(219, 180, 94);
    static int hubSize(int size) { return Math.max(54, size / 5); }
    private static final Color[] SEGMENTS = {
        new Color(79, 43, 40), new Color(45, 73, 39), new Color(73, 58, 34),
        new Color(49, 39, 70), new Color(32, 56, 68), new Color(62, 63, 45)
    };

    static void drawWheel(Graphics2D graphics, int width, int height, List<WheelEntry> entries,
        double angle, boolean enabled, boolean hover, boolean pressed, boolean busy)
    {
        Graphics2D g = (Graphics2D) graphics.create();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
        int size = Math.min(width, height) - 24;
        int x = (width - size) / 2, y = (height - size) / 2;
        double cx = width / 2.0, cy = height / 2.0;
        int total = WheelSelection.totalWeight(entries);
        double before = 0;
        g.setColor(ColorScheme.DARKER_GRAY_COLOR);
        g.fillOval(x, y, size, size);
        for (int i = 0; i < entries.size(); i++)
        {
            WheelEntry entry = entries.get(i);
            boolean xp = !entry.id.startsWith("CUSTOM_") && entry.label.startsWith("Gain ");
            double extent = entry.weight * 360.0 / total;
            Color segment = SEGMENTS[i % SEGMENTS.length];
            if (xp) { segment = XpGoal.valueOf(entry.id).color; }
            g.setPaint(new GradientPaint(x, y, segment.brighter(), x + size, y + size, segment));
            Arc2D arc = new Arc2D.Double(x, y, size, size, before - angle, extent, Arc2D.PIE);
            g.fill(arc);
            g.setColor(ColorScheme.BORDER_COLOR);
            g.setStroke(new BasicStroke(1));
            g.draw(arc);
            double a = Math.toRadians(before + extent / 2 - angle);
            // All icons share a single outer ring; dense pools scale down to avoid overlap.
            double radius = .45;
            int tx = (int) (cx + Math.cos(a) * size * radius);
            int ty = (int) (cy - Math.sin(a) * size * radius);
            if (entry.icon != null)
            {
                int box = Math.min(30, Math.max(6, (int)(2 * size * radius * Math.sin(Math.toRadians(Math.min(90, extent) / 2)) * .82)));
                double scale = Math.min((double) box / entry.icon.getWidth(), (double) box / entry.icon.getHeight());
                int iw = (int) Math.round(entry.icon.getWidth() * scale);
                int ih = (int) Math.round(entry.icon.getHeight() * scale);
                g.drawImage(entry.icon, tx - iw / 2, ty - ih / 2, iw, ih, null);
                drawRadialLabel(g, entry.wheelLabel(), cx, cy, a, extent, size, box);
            }
            else if (xp && extent >= 14)
            {
                g.setFont(FontManager.getRunescapeSmallFont());
                g.setColor(ColorScheme.TEXT_COLOR);
                String label = compactXp(entry.label);
                centered(g, label, tx, ty + 4);
            }
            else { drawRadialLabel(g, xp ? compactXp(entry.label) : entry.wheelLabel(), cx, cy, a, extent, size, 0); }
            before += extent;
        }
        g.setStroke(new BasicStroke(7));
        g.setPaint(new GradientPaint(x, y, GOLD.brighter(), x + size, y + size, GOLD.darker()));
        g.drawOval(x, y, size, size);
        int hub = hubSize(size), hx = width / 2 - hub / 2, hy = height / 2 - hub / 2;
        g.setColor(pressed ? ColorScheme.MEDIUM_GRAY_COLOR
            : hover && enabled ? ColorScheme.DARKER_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
        g.fillOval(hx, hy, hub, hub);
        g.setColor(enabled ? GOLD : ColorScheme.LIGHT_GRAY_COLOR);
        g.setStroke(new BasicStroke(2));
        g.drawOval(hx, hy, hub, hub);
        g.setFont(FontManager.getRunescapeBoldFont());
        centered(g, busy ? "..." : "SPIN", width / 2, height / 2 + 5 + (pressed ? 1 : 0));
        if (hover && enabled)
        {
            g.setColor(GOLD);
            g.drawOval(hx - 3, hy - 3, hub + 6, hub + 6);
        }
        g.setColor(GOLD);
        g.fillPolygon(new int[]{width / 2 - 9, width / 2 + 9, width / 2},
            new int[]{y - 8, y - 8, y + 13}, 3);
        g.dispose();
    }

    private static String compactXp(String label)
    {
        return label.replace("Gain ", "").replace(" XP", "").replace(",000,000", "m").replace(",000", "k");
    }

    private static void drawRadialLabel(Graphics2D graphics, String label, double cx, double cy,
        double angle, double extent, int size, int iconSize)
    {
        double outer = size * .45 - iconSize / 2.0 - 8;
        double inner = Math.max(hubSize(size) / 2.0 + 9, size * .20);
        String initials = java.util.Arrays.stream(label.split("[\\s-]+"))
            .filter(word -> !word.isEmpty()).map(word -> word.substring(0, 1))
            .collect(java.util.stream.Collectors.joining());
        String compact = initials.length() > 1 ? initials : label.substring(0, Math.min(4, label.length()));
        for (String candidate : new String[]{label, compact})
        {
            for (int fontSize = 13; fontSize >= 7; fontSize--)
            {
                Font font = FontManager.getDefaultFont().deriveFont(Font.BOLD, (float)fontSize);
                FontMetrics metrics = graphics.getFontMetrics(font);
                int length = metrics.stringWidth(candidate);
                double start = outer - length;
                double thickness = 2 * start * Math.sin(Math.toRadians(Math.min(90, extent) / 2));
                if (start < inner || thickness < metrics.getHeight() + 2) { continue; }
                Graphics2D g = (Graphics2D)graphics.create();
                g.translate(cx, cy); g.rotate(-angle);
                g.setFont(font); g.setColor(ColorScheme.TEXT_COLOR);
                if (Math.cos(angle) < 0)
                {
                    g.rotate(Math.PI);
                    g.drawString(candidate, (float)-outer, (metrics.getAscent() - metrics.getDescent()) / 2f);
                }
                else { g.drawString(candidate, (float)start, (metrics.getAscent() - metrics.getDescent()) / 2f); }
                g.dispose();
                return;
            }
        }
    }

    static void centered(Graphics2D g, String text, int x, int y)
    {
        g.drawString(text, x - g.getFontMetrics().stringWidth(text) / 2, y);
    }

    private static final BufferedImage CLASSIC_ICON = loadArtwork("classic-wheel.png");
    private static final BufferedImage HEADER = loadArtwork("wheelbound-header.png");

    static BufferedImage createIcon() { return scaledArtwork(CLASSIC_ICON, 32); }
    static BufferedImage headerImage() { return scaledArtwork(HEADER, 210); }

    static BufferedImage loadArtwork(String name)
    {
        try (java.io.InputStream stream = WheelStyle.class.getResourceAsStream(name))
        {
            if (stream == null) { return fallbackArtwork(); }
            BufferedImage image = javax.imageio.ImageIO.read(stream);
            if (image == null) { return fallbackArtwork(); }
            // Remove transparent export margins so each asset fits its UI slot.
            int left = image.getWidth(), top = image.getHeight(), right = -1, bottom = -1;
            for (int y = 0; y < image.getHeight(); y++)
            {
                for (int x = 0; x < image.getWidth(); x++)
                {
                    if ((image.getRGB(x, y) >>> 24) > 16)
                    { left = Math.min(left, x); top = Math.min(top, y); right = Math.max(right, x); bottom = Math.max(bottom, y); }
                }
            }
            return right < left ? image : image.getSubimage(left, top, right - left + 1, bottom - top + 1);
        }
        catch (java.io.IOException ex) { return fallbackArtwork(); }
    }

    private static BufferedImage fallbackArtwork()
    {
        BufferedImage image = new BufferedImage(64, 64, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setColor(GOLD); g.setStroke(new BasicStroke(4)); g.drawOval(4, 4, 56, 56);
        g.setFont(new Font(Font.SERIF, Font.BOLD, 32)); centered(g, "W", 32, 44);
        g.dispose(); return image;
    }

    private static BufferedImage scaledArtwork(BufferedImage source, int width)
    {
        int height = Math.max(1, (int)Math.round(source.getHeight() * (double)width / source.getWidth()));
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
        g.drawImage(source, 0, 0, width, height, null); g.dispose();
        return image;
    }
}

package com.wheelbound;

import java.util.List;
import java.util.Random;

final class WheelSelection
{
    private WheelSelection() {}

    static int totalWeight(List<WheelEntry> entries)
    {
        int total = 0;
        for (WheelEntry entry : entries) { total = Math.addExact(total, entry.weight); }
        return total;
    }

    static int select(List<WheelEntry> entries, Random random)
    {
        int total = totalWeight(entries);
        return total == 0 ? -1 : indexAt(entries, random.nextInt(total));
    }

    static int indexAt(List<WheelEntry> entries, double ticket)
    {
        if (ticket < 0 || ticket >= totalWeight(entries)) { return -1; }
        for (int i = 0; i < entries.size(); i++)
        {
            ticket -= entries.get(i).weight;
            if (ticket < 0) { return i; }
        }
        return -1;
    }

    static double center(List<WheelEntry> entries, int selected)
    {
        double before = 0;
        for (int i = 0; i < selected; i++) { before += entries.get(i).weight; }
        return (before + entries.get(selected).weight / 2.0) * 360 / totalWeight(entries);
    }

    static double targetAngle(double start, List<WheelEntry> entries, int selected)
    {
        double desired = center(entries, selected) - 90;
        return start + ((desired - start) % 360 + 360) % 360 + 5 * 360;
    }
}

package com.wheelbound;

import java.util.Set;

/** Local mapping of the OSRS Wiki Bossing Ladder, with solo GWD ratings where listed. */
enum BossDifficulty
{
    EASY("Easy"), MEDIUM("Medium"), HARD("Hard"), ELITE("Elite"), MASTER("Master"),
    GRANDMASTER("Grandmaster"), UNRATED("Unrated");

    final String title;
    BossDifficulty(String title) { this.title = title; }

    static BossDifficulty of(BossDefinition boss)
    {
        switch (boss.hiscore)
        {
            case BRUTUS: case WINTERTODT: case TEMPOROSS: case BARROWS_CHESTS:
            case OBOR: case BRYOPHYTA: case GIANT_MOLE: case DERANGED_ARCHAEOLOGIST: case SCURRIUS:
                return EASY;
            case AMOXLIATL: case THE_HUEYCOATL: case HESPORI: case CRAZY_ARCHAEOLOGIST:
            case CHAOS_FANATIC: case KRAKEN: case SARACHNIS: case KING_BLACK_DRAGON:
            case ZALCANO: case THERMONUCLEAR_SMOKE_DEVIL: case MIMIC: case THE_ROYAL_TITANS:
            case LUNAR_CHESTS: return MEDIUM;
            case SCORPIA: case CHAOS_ELEMENTAL: case VETION: case CALVARION:
            case VENENATIS: case SPINDEL: case CALLISTO: case ARTIO:
            case DAGANNOTH_PRIME: case DAGANNOTH_REX: case DAGANNOTH_SUPREME:
            case GROTESQUE_GUARDIANS: case SKOTIZO: case TZTOK_JAD: case THE_GAUNTLET:
            case ABYSSAL_SIRE: case CERBERUS: case ARAXXOR: case ALCHEMICAL_HYDRA:
            case KALPHITE_QUEEN: case KRIL_TSUTSAROTH: case COMMANDER_ZILYANA: return HARD;
            case ZULRAH: case VORKATH: case PHANTOM_MUSPAH: case THE_CORRUPTED_GAUNTLET:
            case GENERAL_GRAARDOR: case KREEARRA: case DUKE_SUCELLUS: case THE_WHISPERER:
            case THE_LEVIATHAN: case VARDORVIS: case NEX:
            case TOMBS_OF_AMASCUT: case TOMBS_OF_AMASCUT_EXPERT: return ELITE;
            case CHAMBERS_OF_XERIC: case NIGHTMARE: case PHOSANIS_NIGHTMARE: case YAMA:
            case DOOM_OF_MOKHAIOTL: case THEATRE_OF_BLOOD: case TZKAL_ZUK: case SOL_HEREDIT:
                return MASTER;
            case CHAMBERS_OF_XERIC_CHALLENGE_MODE: case THEATRE_OF_BLOOD_HARD_MODE:
                return GRANDMASTER;
            default: return UNRATED;
        }
    }

    static boolean included(BossDefinition boss, Set<WheelFilter> filters)
    { return filters.contains(WheelFilter.valueOf("BOSS_" + of(boss).name())); }
}

package com.wheelbound;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;

final class BossCatalog
{
    static final List<BossDefinition> ALL = create();
    private BossCatalog() {}

    private static List<BossDefinition> create()
    {
        Map<String, BossProfile> profiles = BossProfile.defaults();
        List<BossDefinition> bosses = new ArrayList<>();
        for (HiscoreSkill boss : HiscoreSkill.values())
        {
            if (boss.getType() != HiscoreSkillType.BOSS) { continue; }
            String name = boss.getName();
            boolean raid = boss.name().startsWith("CHAMBERS_OF_XERIC")
                || boss.name().startsWith("THEATRE_OF_BLOOD") || boss.name().startsWith("TOMBS_OF_AMASCUT");
            List<String> aliases;
            switch (boss)
            {
                case BARROWS_CHESTS: aliases = List.of("Barrows"); break;
                case LUNAR_CHESTS: aliases = List.of("Moons of Peril", "Perilous Moons", "Lunar Chests"); break;
                case THE_GAUNTLET: aliases = List.of(name, "Crystalline Hunllef"); break;
                case THE_CORRUPTED_GAUNTLET: aliases = List.of(name, "Corrupted Gauntlet", "Corrupted Hunllef"); break;
                case MIMIC: aliases = List.of(name, "The Mimic"); break;
                case DAGANNOTH_PRIME: case DAGANNOTH_REX: case DAGANNOTH_SUPREME:
                    aliases = List.of(name, "Dagannoth Kings"); break;
                case TZTOK_JAD: aliases = List.of("TzTok-Jad", "The Fight Caves"); break;
                case TZKAL_ZUK: aliases = List.of("TzKal-Zuk", "The Inferno"); break;
                case SOL_HEREDIT: aliases = List.of("Sol Heredit", "Fortis Colosseum"); break;
                case NIGHTMARE: aliases = List.of("The Nightmare", "Nightmare"); break;
                case THE_ROYAL_TITANS: aliases = List.of("Royal Titans", name); break;
                // Only map modes to exact encounters. Do not count a normal-mode task as a hard-mode task.
                default: aliases = List.of(name);
            }
            BossProfile profile = profiles.get(name);
            if (profile == null)
            {
                for (String alias : aliases)
                {
                    profile = profiles.get(alias);
                    if (profile != null) { break; }
                }
            }
            bosses.add(new BossDefinition(boss, raid, profile, aliases));
        }
        return List.copyOf(bosses);
    }
}

package com.wheelbound;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Comparator;
import net.runelite.api.Model;

/** Small local CA-model preview. Does not change the game's model or rasterizer state. */
final class MonsterThumbnail
{
    private MonsterThumbnail() {}

    static BufferedImage render(Model model, int yaw, int pitch)
    {
        if (model == null || model.getVerticesCount() == 0 || model.getFaceCount() == 0) { return null; }
        int count = model.getVerticesCount();
        double[] x = new double[count], y = new double[count], depth = new double[count];
        double angle = yaw * Math.PI / 1024, tilt = pitch * Math.PI / 1024;
        double minX = Double.POSITIVE_INFINITY, maxX = Double.NEGATIVE_INFINITY;
        double minY = Double.POSITIVE_INFINITY, maxY = Double.NEGATIVE_INFINITY;
        float[] vx = model.getVerticesX(), vy = model.getVerticesY(), vz = model.getVerticesZ();
        for (int i = 0; i < count; i++)
        {
            x[i] = vx[i] * Math.cos(angle) + vz[i] * Math.sin(angle);
            double z = vz[i] * Math.cos(angle) - vx[i] * Math.sin(angle);
            y[i] = vy[i] * Math.cos(tilt) - z * Math.sin(tilt);
            depth[i] = z * Math.cos(tilt) + vy[i] * Math.sin(tilt);
            minX = Math.min(minX, x[i]); maxX = Math.max(maxX, x[i]);
            minY = Math.min(minY, y[i]); maxY = Math.max(maxY, y[i]);
        }
        double scale = 58 / Math.max(1, Math.max(maxX - minX, maxY - minY));
        int[] px = new int[count], py = new int[count];
        for (int i = 0; i < count; i++)
        { px[i] = (int)Math.round(32 + (x[i] - (minX + maxX) / 2) * scale); py[i] = (int)Math.round(32 + (y[i] - (minY + maxY) / 2) * scale); }
        int[] a = model.getFaceIndices1(), b = model.getFaceIndices2(), c = model.getFaceIndices3();
        Integer[] order = new Integer[model.getFaceCount()];
        Arrays.setAll(order, i -> i);
        Arrays.sort(order, Comparator.comparingDouble((Integer i) -> depth[a[i]] + depth[b[i]] + depth[c[i]]).reversed());
        BufferedImage image = new BufferedImage(64, 64, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        int[] colors = model.getFaceColors1(), third = model.getFaceColors3();
        byte[] alpha = model.getFaceTransparencies();
        short[] unlit = model.getUnlitFaceColors();
        for (int i : order)
        {
            if (third[i] == -2) { continue; }
            int hsl = unlit != null ? unlit[i] & 0xffff : colors[i] & 0xffff;
            g.setColor(color(hsl, alpha == null ? 255 : 255 - (alpha[i] & 255)));
            g.fillPolygon(new int[]{px[a[i]], px[b[i]], px[c[i]]}, new int[]{py[a[i]], py[b[i]], py[c[i]]}, 3);
        }
        g.dispose();
        return image;
    }

    private static Color color(int packed, int alpha)
    {
        double h = ((packed >> 10) & 63) / 64.0, s = ((packed >> 7) & 7) / 8.0, l = (packed & 127) / 128.0;
        double chroma = (1 - Math.abs(2 * l - 1)) * s, x = chroma * (1 - Math.abs(h * 6 % 2 - 1)), m = l - chroma / 2;
        double r = 0, g = 0, b = 0;
        switch ((int)(h * 6))
        {
            case 0: r = chroma; g = x; break;
            case 1: r = x; g = chroma; break;
            case 2: g = chroma; b = x; break;
            case 3: g = x; b = chroma; break;
            case 4: r = x; b = chroma; break;
            default: r = chroma; b = x; break;
        }
        return new Color((int)((r + m) * 255), (int)((g + m) * 255), (int)((b + m) * 255), alpha);
    }
}

