package com.wheelbound;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import java.util.stream.Collectors;

/** Profile-local custom lists. Stable IDs keep duplicate labels and checkbox state independent. */
final class CustomWheels
{
    static final String KEY = "customWheels";
    // Gson restores these fields from saved JSON; keep them writable.
    @SuppressWarnings("FieldMayBeFinal")
    private int version = 1;
    @SuppressWarnings("FieldMayBeFinal")
    private List<CustomWheel> wheels = new ArrayList<>();

    static final class Item
    {
        String id = UUID.randomUUID().toString();
        String name;
        boolean enabled = true;
        Item(String name) { this.name = name; }
    }

    static final class CustomWheel
    {
        String id = UUID.randomUUID().toString();
        String name;
        List<Item> items = new ArrayList<>();
        CustomWheel(String name) { this.name = name; }
        List<WheelEntry> entries()
        { return items.stream().map(i -> new WheelEntry("CUSTOM_" + i.id, i.name, null, 1)).collect(Collectors.toList()); }
        String exclusions()
        { return items.stream().filter(i -> !i.enabled).map(i -> "CUSTOM_" + i.id).collect(Collectors.joining(",")); }
        @Override public String toString() { return "Custom: " + name; }
    }

    List<CustomWheel> wheels() { return List.copyOf(wheels); }
    CustomWheel find(String id) { return wheels.stream().filter(w -> w.id.equals(id)).findFirst().orElse(null); }
    CustomWheel create(String name)
    {
        String clean = text(name, 80);
        if (wheels.stream().anyMatch(w -> w.name.equalsIgnoreCase(clean)))
        { throw new IllegalArgumentException("A custom wheel already has that name."); }
        CustomWheel wheel = new CustomWheel(clean); wheels.add(wheel); return wheel;
    }
    void add(CustomWheel wheel, String name) { wheel.items.add(new Item(text(name, 200))); }
    void remove(CustomWheel wheel) { wheels.remove(wheel); }
    String save(Gson gson) { return gson.toJson(this); }

    static CustomWheels load(Gson gson, String saved)
    {
        if (saved == null || saved.isBlank()) { return new CustomWheels(); }
        try
        {
            CustomWheels data = gson.fromJson(saved, CustomWheels.class);
            if (data == null || data.version != 1 || data.wheels == null) { throw new IllegalArgumentException(); }
            Set<String> ids = new HashSet<>();
            for (CustomWheel wheel : data.wheels)
            {
                if (wheel == null || wheel.items == null || invalidId(wheel.id) || !ids.add(wheel.id))
                { throw new IllegalArgumentException(); }
                wheel.name = text(wheel.name, 80);
                for (Item item : wheel.items)
                {
                    if (item == null || invalidId(item.id) || !ids.add(item.id)) { throw new IllegalArgumentException(); }
                    item.name = text(item.name, 200);
                }
            }
            return data;
        }
        catch (RuntimeException ex)
        { throw new IllegalArgumentException("Saved custom wheels could not be read. Your saved data has been kept.", ex); }
    }

    private static boolean invalidId(String id)
    { return id == null || !id.matches("[a-zA-Z0-9-]+") || id.length() > 80; }
    private static String text(String name, int limit)
    {
        if (name == null || name.isBlank()) { throw new IllegalArgumentException("Enter a name first."); }
        String clean = name.strip();
        if (clean.length() > limit) { throw new IllegalArgumentException("Use " + limit + " characters or fewer."); }
        if (clean.codePoints().anyMatch(Character::isISOControl))
        { throw new IllegalArgumentException("Use a single line of text."); }
        return clean;
    }
}

package com.wheelbound;

import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Predicate;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/** Reads are client-thread-only. These access checks supplement recommended combat stats. */
final class AccountAccess
{
    private static final Map<String, Quest> QUESTS = Map.ofEntries(
        Map.entry("Zulrah", Quest.REGICIDE),
        Map.entry("Vorkath", Quest.DRAGON_SLAYER_II),
        Map.entry("Phantom Muspah", Quest.SECRETS_OF_THE_NORTH),
        Map.entry("The Gauntlet", Quest.SONG_OF_THE_ELVES),
        Map.entry("The Corrupted Gauntlet", Quest.SONG_OF_THE_ELVES),
        Map.entry("Zalcano", Quest.SONG_OF_THE_ELVES),
        Map.entry("Duke Sucellus", Quest.DESERT_TREASURE_II__THE_FALLEN_EMPIRE),
        Map.entry("Vardorvis", Quest.DESERT_TREASURE_II__THE_FALLEN_EMPIRE),
        Map.entry("The Leviathan", Quest.DESERT_TREASURE_II__THE_FALLEN_EMPIRE),
        Map.entry("The Whisperer", Quest.DESERT_TREASURE_II__THE_FALLEN_EMPIRE),
        Map.entry("Barrows Chests", Quest.PRIEST_IN_PERIL),
        Map.entry("Grotesque Guardians", Quest.PRIEST_IN_PERIL),
        Map.entry("Araxxor", Quest.PRIEST_IN_PERIL),
        Map.entry("Nightmare", Quest.PRIEST_IN_PERIL),
        Map.entry("Phosani's Nightmare", Quest.PRIEST_IN_PERIL),
        Map.entry("Lunar Chests", Quest.PERILOUS_MOONS),
        Map.entry("Amoxliatl", Quest.THE_HEART_OF_DARKNESS),
        Map.entry("Doom of Mokhaiotl", Quest.THE_FINAL_DAWN),
        Map.entry("Brutus", Quest.THE_IDES_OF_MILK),
        Map.entry("Shellbane Gryphon", Quest.TROUBLED_TORTUGANS),
        Map.entry("Nex", Quest.THE_FROZEN_DOOR));
    private static final Set<String> GOD_WARS = Set.of("General Graardor", "Kree'Arra", "Commander Zilyana", "K'ril Tsutsaroth", "Nex");

    static boolean questsAllow(BossDefinition boss, Predicate<Quest> complete)
    {
        Quest quest = QUESTS.get(boss.name);
        if (quest != null && !complete.test(quest)) { return false; }
        if (GOD_WARS.contains(boss.name) && !complete.test(Quest.TROLL_STRONGHOLD)) { return false; }
        return !boss.name.startsWith("Tombs of Amascut") || complete.test(Quest.BENEATH_CURSED_SANDS);
    }

    static Predicate<BossDefinition> requirements(Client client)
    {
        Map<Quest, Boolean> states = new EnumMap<>(Quest.class);
        return boss -> questsAllow(boss, quest -> states.computeIfAbsent(quest,
            q -> q.getState(client) == QuestState.FINISHED))
            && (!boss.name.equals("Grotesque Guardians") || client.getVarbitValue(VarbitID.GARGBOSS_UNLOCKED_ROOF) != 0);
    }

    static final class SlayerTask
    {
        final String name, area;
        final int remaining;
        final boolean wilderness;
        SlayerTask(String name, String area, int remaining, boolean wilderness)
        { this.name = CaEncounter.normalize(name); this.area = CaEncounter.normalize(area); this.remaining = remaining; this.wilderness = wilderness; }
        static SlayerTask unavailable() { return new SlayerTask("", "", 0, false); }
    }

    static SlayerTask slayerTask(Client client)
    {
        int count = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
        if (count <= 0) { return SlayerTask.unavailable(); }
        int target = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
        List<Integer> rows = target == 98
            ? client.getDBRowsByValue(DBTableID.SlayerTaskSublist.ID, DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
                0, client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID))
            : client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, target);
        if (rows.isEmpty()) { return SlayerTask.unavailable(); }
        int row = target == 98 ? (Integer)client.getDBTableField(rows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0] : rows.get(0);
        String name = (String)client.getDBTableField(row, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];
        int areaId = client.getVarpValue(VarPlayerID.SLAYER_AREA);
        String area = "";
        if (areaId > 0)
        {
            List<Integer> areas = client.getDBRowsByValue(DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, areaId);
            if (areas.isEmpty()) { return SlayerTask.unavailable(); }
            area = (String)client.getDBTableField(areas.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0)[0];
        }
        return new SlayerTask(name, area, count, client.getVarbitValue(VarbitID.SLAYER_MASTER) == 7);
    }

    static boolean taskAllows(String encounter, SlayerTask task)
    {
        String name = CaEncounter.normalize(encounter);
        String assignment, location;
        switch (name)
        {
            case "shellbanegryphon": assignment = "gryphons"; location = "greatconch"; break;
            case "abyssalsire": assignment = "abyssaldemons"; location = "abyss"; break;
            case "kraken": case "cavekraken": assignment = "cavekraken"; location = "krakencove"; break;
            case "cerberus": assignment = "hellhounds"; location = "taverleydungeon"; break;
            case "grotesqueguardians": assignment = "gargoyles"; location = "slayertower"; break;
            case "alchemicalhydra": assignment = "hydras"; location = "karuulmslayerdungeon"; break;
            case "araxxor": assignment = "araxytes"; location = "araxytecave"; break;
            case "thermonuclearsmokedevil": assignment = "smokedevils"; location = "smokedevildungeon"; break;
            default: return true;
        }
        String assigned = task.name;
        boolean matches = assigned.equals(assignment) || assigned.equals(name)
            || name.equals("kraken") && assigned.equals("cavekrakenboss");
        return task.remaining > 0 && !task.wilderness && matches
            && (task.area.isEmpty() || task.area.contains(location));
    }

}

package com.wheelbound;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.DBTableID;

/** Client-thread reads of the same released quest rows and checks used by the quest journal. */
final class QuestPool
{
    static final String COMPLETE = "Congrats, you have completed all the quests!";
    static final int REQUIREMENT_CHECK = 5989;
    static final int DIFFICULTY_NAMES = 2094;
    final List<WheelEntry> entries;
    final boolean allComplete;

    private QuestPool(List<WheelEntry> entries, boolean allComplete)
    { this.entries = List.copyOf(entries); this.allComplete = allComplete; }

    static QuestPool read(Client client, Set<WheelFilter> filters, WheelIconProvider icons)
    {
        List<Integer> rows = client.getDBTableRows(DBTableID.Quest.ID);
        if (rows == null || rows.isEmpty()) { throw new IllegalStateException("Quest data unavailable"); }
        EnumComposition difficulties = client.getEnum(DIFFICULTY_NAMES);
        if (difficulties == null) { throw new IllegalStateException("Quest difficulties unavailable"); }
        List<WheelEntry> entries = new ArrayList<>();
        int total = 0, unfinished = 0;
        for (int row : rows)
        {
            // Exclude unreleased rows, miniquests and subquests; RFD appears once as its parent quest.
            if (integer(client, row, DBTableID.Quest.COL_RELEASE_TYPE) != 2
                || integer(client, row, DBTableID.Quest.COL_TYPE) != 0
                || integer(client, row, DBTableID.Quest.COL_PARENT_QUEST) != -1) { continue; }
            total++;
            client.runScript(ScriptID.QUEST_STATUS_GET, row);
            int state = client.getIntStack()[0];
            if (state == 2) { continue; }
            if (state != 0 && state != 1) { throw new IllegalStateException("Unknown quest state"); }
            unfinished++;
            String difficulty = difficulties.getStringValue(integer(client, row, DBTableID.Quest.COL_DIFFICULTY));
            if (!includesDifficulty(filters, difficulty)) { continue; }
            if (filters.contains(WheelFilter.QUEST_ELIGIBLE))
            {
                client.runScript(REQUIREMENT_CHECK, row);
                if (client.getIntStack()[0] != 1) { continue; }
            }
            String name = (String)client.getDBTableField(row, DBTableID.Quest.COL_DISPLAYNAME, 0)[0];
            entries.add(icons.quest(row, name));
        }
        if (total == 0) { throw new IllegalStateException("No released quests found"); }
        return new QuestPool(entries, unfinished == 0);
    }

    static boolean includesDifficulty(Set<WheelFilter> filters, String difficulty)
    {
        for (WheelFilter filter : filters)
        {
            if (filter.wheel == WheelType.QUESTING && filter.section.equals("Quest difficulty")
                && filter.title.equalsIgnoreCase(difficulty)) { return true; }
        }
        return false;
    }

    private static int integer(Client client, int row, int column)
    { return (Integer)client.getDBTableField(row, column, 0)[0]; }
}

package com.wheelbound;

import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.*;
import net.runelite.client.ui.ColorScheme;

/** Reusable manual selection for any wheel. Eligible unchecked entries remain listed. EDT only. */
final class BossChecklist extends JPanel
{
    private final Set<String> excluded = new TreeSet<>();
    private final JPanel rows = new JPanel();
    private final Consumer<String> changed;
    private final Consumer<WheelEntry> delete;
    private List<WheelEntry> entries = List.of();

    BossChecklist(String heading, String saved, Consumer<String> changed)
    { this(heading, saved, changed, null); }

    BossChecklist(String heading, String saved, Consumer<String> changed, Consumer<WheelEntry> delete)
    {
        this.changed = changed;
        this.delete = delete;
        if (saved != null && !saved.isBlank()) { excluded.addAll(Arrays.asList(saved.split(","))); }
        setLayout(new BorderLayout(0, 5)); setOpaque(false);
        JLabel title = new JLabel(heading);
        title.setForeground(ColorScheme.TEXT_COLOR);
        add(title, BorderLayout.NORTH);
        rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
        rows.setBackground(ColorScheme.DARK_GRAY_COLOR);
        rows.setBorder(BorderFactory.createEmptyBorder(0, 0, 12, 0));
        JScrollPane scroll = new JScrollPane(rows);
        scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        scroll.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
        scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.getVerticalScrollBar().setUnitIncrement(24);
        scroll.setPreferredSize(new Dimension(200, 170));
        add(scroll, BorderLayout.CENTER);

    }

    void updateEntries(List<WheelEntry> values)
    {
        boolean same = entries.size() == values.size();
        for (int i = 0; same && i < values.size(); i++)
        { same = entries.get(i).id.equals(values.get(i).id); }
        entries = List.copyOf(values);
        if (same) { return; }
        rows.removeAll();
        for (WheelEntry entry : entries)
        {
            JCheckBox box = new JCheckBox("<html><div style='width:" + (delete == null ? 120 : 100)
                + "px'>" + escape(entry.label) + "</div></html>", !excluded.contains(entry.id));
            box.setToolTipText("<html>" + escape(entry.label) + "</html>");
            box.setOpaque(false); box.setForeground(ColorScheme.TEXT_COLOR);
            box.setFont(net.runelite.client.ui.FontManager.getDefaultFont().deriveFont(12f));
            box.setBorder(BorderFactory.createEmptyBorder(5, 3, 5, 3));
            box.setEnabled(isEnabled());
            box.addActionListener(e -> {
                if (box.isSelected()) { excluded.remove(entry.id); } else { excluded.add(entry.id); }
                changed.accept(String.join(",", excluded));
            });
            if (delete == null) { rows.add(box); }
            else
            {
                JPanel row = new JPanel(new BorderLayout()); row.setOpaque(false);
                row.setAlignmentX(Component.LEFT_ALIGNMENT);
                JButton remove = new JButton(new TrashIcon());
                remove.setContentAreaFilled(false); remove.setBorderPainted(false); remove.setOpaque(false);
                remove.setToolTipText("Delete entry: " + entry.label);
                remove.getAccessibleContext().setAccessibleName("Delete entry: " + entry.label);
                remove.setPreferredSize(new Dimension(26, 26));
                remove.setMargin(new Insets(3, 3, 3, 3)); remove.setEnabled(isEnabled());
                remove.addActionListener(e -> delete.accept(entry));
                row.add(box, BorderLayout.CENTER); row.add(remove, BorderLayout.EAST);
                row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
                rows.add(row);
            }
        }
        rows.revalidate(); rows.repaint();
    }

    List<WheelEntry> included(List<WheelEntry> values)
    {
        List<WheelEntry> result = new ArrayList<>();
        for (WheelEntry entry : values) { if (!excluded.contains(entry.id)) { result.add(entry); } }
        return List.copyOf(result);
    }

    void restore(String saved)
    {
        excluded.clear();
        if (saved != null && !saved.isBlank()) { excluded.addAll(Arrays.asList(saved.split(","))); }
        List<WheelEntry> current = entries; entries = List.of(); updateEntries(current);
    }
    @Override public void setEnabled(boolean enabled)
    {
        super.setEnabled(enabled);
        if (rows != null) { enableChildren(rows, enabled); }
    }

    private static void enableChildren(Container parent, boolean enabled)
    {
        for (Component child : parent.getComponents())
        { child.setEnabled(enabled); if (child instanceof Container) { enableChildren((Container)child, enabled); } }
    }

    static String escape(String text)
    { return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;"); }

    private static final class TrashIcon implements Icon
    {
        public int getIconWidth() { return 12; }
        public int getIconHeight() { return 14; }
        public void paintIcon(Component component, Graphics graphics, int x, int y)
        {
            Graphics g = graphics.create(); g.translate(x, y);
            g.setColor(component.isEnabled() ? new Color(230, 105, 105) : Color.GRAY);
            g.drawRect(3, 1, 5, 2); g.drawLine(0, 3, 11, 3);
            g.drawRect(2, 4, 7, 9); g.drawLine(4, 6, 4, 11); g.drawLine(7, 6, 7, 11); g.dispose();
        }
    }
}

package com.wheelbound;

import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;

/** Client-thread-only, account-local state. Static task metadata is owned separately by BossData. */
final class CombatAchievementCache
{
    private String account;
    private boolean ready;
    private Set<String> incomplete = Set.of();
    private int[] completion = new int[0];

    void reset()
    {
        account = null;
        ready = false;
        incomplete = Set.of();
        completion = new int[0];
    }

    void refresh(String identity, Map<String, List<Integer>> tasks,
        IntUnaryOperator readVarp)
    {
        reset();
        if (identity == null || tasks.isEmpty()) { return; }
        int[] flags = new int[BossData.COMPLETION.length];
        for (int i = 0; i < flags.length; i++) { flags[i] = readVarp.applyAsInt(BossData.COMPLETION[i]); }
        Set<String> open = new HashSet<>();
        for (BossDefinition boss : BossCatalog.ALL)
        {
            for (String encounter : boss.caEncounters)
            {
                for (int id : tasks.getOrDefault(encounter, List.of()))
                {
                    if (id >= 0 && id / 32 < flags.length && !BossData.isComplete(flags[id / 32], id % 32))
                    {
                        open.add(boss.hiscore.name());
                    }
                }
            }
        }
        incomplete = Set.copyOf(open);
        completion = flags;
        account = identity;
        ready = true;
    }

    boolean isReady(String identity) { return ready && account.equals(identity); }
    boolean hasIncomplete(String identity, BossDefinition boss)
    {
        return isReady(identity) && incomplete.contains(boss.hiscore.name());
    }

    boolean hasIncomplete(String identity, CaEncounter encounter, Set<CaTier> excludedTiers)
    {
        return !incompleteTasks(identity, encounter, excludedTiers).isEmpty();
    }

    List<CaEncounter.Task> incompleteTasks(String identity, CaEncounter encounter, Set<CaTier> excludedTiers)
    {
        if (!isReady(identity)) { return List.of(); }
        return encounter.tasks.stream().filter(task -> !excludedTiers.contains(task.tier)
            && task.id >= 0 && task.id / 32 < completion.length
            && !BossData.isComplete(completion[task.id / 32], task.id % 32))
            .collect(java.util.stream.Collectors.toUnmodifiableList());
    }

    static boolean isCompletionVarp(int id)
    {
        for (int varp : BossData.COMPLETION) { if (id == varp) { return true; } }
        return false;
    }
}

